#!/usr/bin/env node
/**
 * sennel/docs/commands/enrich.js
 *
 * AI で analysis.json の各エントリーに summary/detail/chapter/role を付与する。
 * scan 後に実行し、enriched analysis.json を生成する。
 *
 * バッチ処理: エントリーを固定サイズのバッチに分割して AI を呼び出す。
 * レジューム: 各バッチ完了後に analysis.json を保存。既に enriched なエントリーはスキップ。
 */

import fs from "fs";
import path from "path";
import { parseArgs } from "../../lib/cli.js";
import { managedOutputDir, resolveConcurrency, resolvePromptCharacterLimit } from "../../lib/config.js";
import { minify } from "../lib/minify.js";
import { ConcurrentBatchResult } from "../lib/concurrency.js";
import { loadFullAnalysis } from "../lib/command-context.js";
import { resolveChaptersOrder } from "../lib/template-merger.js";
import { buildCategoryMapFromDocs, mergeChapters } from "../lib/chapter-resolver.js";
import { filterByDocsExclude } from "../lib/analysis-filter.js";
import { createLogger } from "../../lib/progress.js";
import { translate } from "../../lib/i18n.js";
import { repairJson } from "../../lib/json-parse.js";
import { iterateAnalysisCategories } from "../lib/analysis-entry.js";
import { container } from "../../lib/container.js";
import { resolveDocsContext } from "../lib/docs-context.js";
import { Command } from "../../lib/command.js";
import { AtomicJsonFile } from "../../lib/atomic-json-file.js";
import { PromptBuilder } from "../../lib/prompt-builder.js";
import { DocumentationAgent } from "../lib/documentation-agent.js";
import {
  LinearPromptBatchTopology,
  PromptBatchExecutor,
  PromptBatchPlan,
  PromptExecutionLimit,
  PromptInputBuilder,
  PromptRequestLimit,
} from "../../lib/prompt-batching.js";
import { DocumentationAnalysisPromptElement, documentationSourceRevision } from "../lib/prompt-elements.js";
import {
  DocumentationEnrichPromptEnvelope,
  DocumentationEnrichmentResponseContract,
  reduceDocumentationEnrichment,
} from "../lib/documentation-enrich-batching.js";

const logger = createLogger("enrich");
function printHelp() {
  const t = translate();
  const h = t.raw("ui:help.cmdHelp.enrich");
  const opts = h.options;
  console.log(
    [
      h.usage,
      "",
      h.desc,
      "",
      "Options:",
      `  ${opts.agent}`,
      `  ${opts.dryRun}`,
      `  ${opts.stdout}`,
      `  ${opts.help}`,
    ].join("\n"),
  );
}

/**
 * analysis からカテゴリ横断でフラットなエントリーリストを収集する。
 * 各エントリーには category と index を付与。
 *
 * @param {Object} analysis - analysis.json のデータ
 * @returns {Array<{category: string, index: number, file: string, lines: number, enriched: boolean}>}
 */
function collectEntries(analysis) {
  const entries = [];
  for (const [cat, catData] of iterateAnalysisCategories(analysis)) {
    const items = catData.entries;
    for (let i = 0; i < items.length; i++) {
      entries.push({
        category: cat,
        index: i,
        file: items[i].file || items[i].name || `${cat}.entries[${i}]`,
        lines: items[i].lines || 0,
        enriched: !!items[i].enrich?.processedAt,
      });
    }
  }
  return entries;
}


function entryKey(category, index) {
  return `${category}:${index}`;
}

/**
 * バッチ用の enrich プロンプトを生成する。
 * 対象ファイルの一覧を明示し、AI にそれぞれのソースを読ませる。
 *
 * @param {string[]} chapters - Chapter file names from preset
 * @param {Array<{category: string, index: number, file: string}>} batchEntries - バッチ内のエントリー
 * @returns {string} Prompt text
 */
const ENRICH_FMT_FALLBACK = [
  "## Output format",
  "Return a JSON object with the following structure:",
  '{"entries": [{"elementId": "<copy target elementId>", "category": "<copy target category>", "index": 0, "summary": "...", "detail": "...", "chapter": "...", "role": "other", "keywords": ["...", "...", "..."], "app": null}]}',
  "Copy the exact elementId, category and numeric index from each target identity; example values are placeholders.",
  "Return ONLY valid JSON, no markdown fences, no explanation text.",
].join("\n");

function buildEnrichPrompt(chapters, batchEntries, opts) {
  const pb = _buildEnrichPromptBuilder(chapters, batchEntries, opts);
  const built = pb.build();
  const parts = [];
  if (built.systemPrompt) parts.push(built.systemPrompt);
  if (built.fmtFallback) parts.push(built.fmtFallback);
  if (built.userPrompt) parts.push(built.userPrompt);
  return parts.join("\n\n");
}

function _buildEnrichPromptBuilder(chapters, batchEntries, opts) {
  const pb = new PromptBuilder();
  pb.setRole("Analyze the following source code extracts and add structured metadata.");

  // Target files
  const fileParts = [];
  for (const entry of batchEntries) {
    fileParts.push(`### [${entry.category}:${entry.index}] ${entry.file}`);
    if (entry.essential) {
      fileParts.push("```");
      fileParts.push(entry.essential);
      fileParts.push("```");
    }
    fileParts.push("");
  }
  pb.addUserPrompt("## Target files", fileParts.join("\n"));

  // Chapter list
  const chapterLines = ["Each entry should be assigned to one of these chapters:"];
  for (const ch of chapters) {
    if (typeof ch === "string") {
      chapterLines.push(`- ${ch.replace(/\.md$/, "")}`);
    } else {
      const name = ch.chapter.replace(/\.md$/, "");
      chapterLines.push(ch.desc ? `- ${name}: ${ch.desc}` : `- ${name}`);
    }
  }
  pb.addUserPrompt("## Available chapters", chapterLines.join("\n"));

  // Monorepo app assignment (optional)
  const monorepoApps = opts?.monorepoApps;
  const hasMonorepoApps = Array.isArray(monorepoApps) && monorepoApps.length > 0;
  if (hasMonorepoApps) {
    const appLines = [
      "This is a monorepo. Assign each entry to one of these apps based on its file path:",
    ];
    for (const app of monorepoApps) {
      appLines.push(`- "${app.name}" (path prefix: ${app.path})`);
    }
    appLines.push('Add an `"app"` field to each entry with the app name.');
    pb.addUserPrompt("## Monorepo apps", appLines.join("\n"));
  }

  // JSON schema for structured output
  const schemaProperties = {
    category: { type: "string" },
    index: { type: "integer" },
    summary: { type: "string" },
    detail: { type: "string" },
    chapter: { type: "string" },
    role: { type: "string", enum: ["controller", "model", "lib", "config", "cli", "middleware", "test", "migration", "route", "view", "other"] },
    keywords: { type: "array", items: { type: "string" } },
    app: { type: ["string", "null"] },
  };
  const requiredFields = ["category", "index", "summary", "detail", "chapter", "role", "keywords", "app"];
  pb.setJsonSchema({
    type: "object",
    properties: {
      entries: {
        type: "array",
        items: {
          type: "object",
          properties: schemaProperties,
          required: requiredFields,
          additionalProperties: false,
        },
      },
    },
    required: ["entries"],
    additionalProperties: false,
  });
  pb.setFmtFallback(ENRICH_FMT_FALLBACK);

  // Rules
  const ruleLines = [
    "- Return ONLY valid JSON, no markdown fences, no explanation text.",
    "- Return entries in the top-level `entries` array.",
    "- The `category` field must match the original category in the target file marker.",
    "- The `index` field must match the original index provided above.",
    "- `summary` should be concise (1-2 sentences).",
    "- `detail`: 3-5 sentences summarizing key implementation patterns and logic.",
    "- `chapter` must be one of the available chapter names (without .md extension).",
  ];
  if (hasMonorepoApps) {
    ruleLines.push("- `app` must be one of the monorepo app names listed above, or null if file does not belong to any app.");
  } else {
    ruleLines.push("- `app` must be null.");
  }
  const LANG_NAMES = { en: "English", ja: "Japanese", zh: "Chinese", ko: "Korean", fr: "French", de: "German", es: "Spanish", pt: "Portuguese", it: "Italian", ru: "Russian" };
  const lang = opts?.lang || "en";
  const langName = LANG_NAMES[lang] || lang;
  ruleLines.push("- `keywords` must be in English. Include 3-10 search keywords with synonyms and related terms.");
  ruleLines.push(`- Write summary, detail, and any descriptive content strictly in ${langName}.`);
  pb.setRules(ruleLines.join("\n"));

  return pb;
}

/**
 * Parse the AI response and extract enrichment data.
 *
 * @param {string} response - Raw AI response
 * @returns {Object|null} Parsed enrichment data
 */
function parseEnrichResponse(response) {
  try {
    const parsed = JSON.parse(repairJson(response));
    if (!Array.isArray(parsed?.entries)) return parsed;
    const grouped = {};
    for (const entry of parsed.entries) {
      const category = typeof entry?.category === "string" ? entry.category : "";
      if (!category) continue;
      if (!grouped[category]) grouped[category] = [];
      const { category: _category, app, ...rest } = entry;
      grouped[category].push(app == null ? rest : { ...rest, app });
    }
    return grouped;
  } catch (_) {
    return null;
  }
}


/**
 * Merge enrichment data into the analysis object (mutates analysis).
 *
 * @param {Object} analysis - Original analysis data
 * @param {Object} enrichment - AI-generated enrichment data
 * @param {Object} [opts] - Merge options
 * @returns {Object} Enriched analysis (same reference)
 */
function mergeEnrichment(analysis, enrichment, opts = {}) {
  const processedAt = opts.now || new Date().toISOString();
  const attemptsByKey = opts.attemptsByKey || new Map();
  const onWarn = opts.onWarn || (() => {});
  const respondedKeys = new Set();

  for (const cat of Object.keys(enrichment)) {
    if (!analysis[cat]) continue;
    const enrichedItems = enrichment[cat];
    if (!Array.isArray(enrichedItems)) continue;

    const items = analysis[cat].entries;
    if (!Array.isArray(items)) continue;

    for (const entry of enrichedItems) {
      if (!entry || typeof entry !== "object") continue;
      const idx = entry.index;
      if (idx == null || idx < 0 || idx >= items.length) continue;
      respondedKeys.add(entryKey(cat, idx));

      // Validate chapter if validChapters set is provided
      let chapter = entry.chapter || items[idx].chapter;
      const validChapters = opts.validChapters;
      if (chapter && validChapters && !validChapters.has(chapter)) {
        onWarn(`WARN: invalid chapter "${chapter}" for ${cat}[${idx}], skipped`);
        chapter = items[idx].chapter || null;
      }

      items[idx] = {
        ...items[idx],
        summary: entry.summary || items[idx].summary,
        detail: entry.detail || items[idx].detail,
        chapter,
        role: entry.role || items[idx].role,
        enrich: {
          processedAt,
          attempts: attemptsByKey.get(entryKey(cat, idx)) ?? items[idx].enrich?.attempts ?? 1,
        },
        ...(entry.app ? { app: entry.app } : {}),
        ...(Array.isArray(entry.keywords) && entry.keywords.length > 0 ? { keywords: entry.keywords } : (items[idx].keywords ? { keywords: items[idx].keywords } : {})),
      };

      if (!entry.summary) {
        const file = items[idx].file || items[idx].name || `${cat}.entries[${idx}]`;
        onWarn(`WARN: summary missing for ${file} (category=${cat}, index=${idx})`);
      }
    }
  }

  for (const [key, attempts] of attemptsByKey.entries()) {
    if (respondedKeys.has(key)) continue;
    const [category, rawIndex] = key.split(":");
    const index = Number(rawIndex);
    const item = analysis?.[category]?.entries?.[index];
    if (!item) continue;
    item.enrich = {
      ...item.enrich,
      attempts,
    };
  }

  analysis.enrichedAt = processedAt;
  return analysis;
}

function buildAttemptsByKey(analysis, batchEntries, attemptsUsed) {
  const attempts = new Map();
  for (const entry of batchEntries) {
    const current = analysis?.[entry.category]?.entries?.[entry.index]?.enrich?.attempts ?? 0;
    attempts.set(entryKey(entry.category, entry.index), current + attemptsUsed);
  }
  return attempts;
}

export class EnrichmentCheckpointCoordinator {
  constructor({ analysis, chapters, onWarn = () => {}, onCheckpoint = () => {} }) {
    if (!analysis || typeof analysis !== "object") throw new Error("enrichment analysis is required");
    if (!Array.isArray(chapters)) throw new Error("enrichment chapters must be an array");
    this.analysis = analysis;
    this.validChapterNames = new Set(chapters.map((chapter) => (
      typeof chapter === "string" ? chapter : chapter.chapter
    ).replace(/\.md$/, "")));
    this.onWarn = onWarn;
    this.onCheckpoint = onCheckpoint;
  }

  apply(batchResults) {
    // Enrichment is one logical publication. Never expose checkpoints from a
    // successful prefix when a later independent batch failed.
    batchResults.throwIfErrors();
    let totalEnriched = 0;
    for (const result of batchResults) {
      const { batch, enrichment } = result.value;
      const attemptsByKey = buildAttemptsByKey(this.analysis, batch, 1);
      mergeEnrichment(this.analysis, enrichment, {
        batchEntries: batch,
        attemptsByKey,
        validChapters: this.validChapterNames,
        onWarn: this.onWarn,
      });
      const batchCount = Object.values(enrichment).reduce(
        (sum, entries) => sum + (Array.isArray(entries) ? entries.length : 0),
        0,
      );
      totalEnriched += batchCount;
    }
    this.onCheckpoint(this.analysis, totalEnriched);
    return totalEnriched;
  }
}

/**
 * analysis.json をディスクに保存する。
 */
function saveAnalysis(root, analysis) {
  const outputDir = managedOutputDir(root);
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }
  const outputPath = path.join(outputDir, "analysis.json");
  new AtomicJsonFile(outputPath).write(analysis);
  return outputPath;
}

// ---------------------------------------------------------------------------
// メイン
// ---------------------------------------------------------------------------

async function runEnrich(ctx, rawArgs) {
  if (!ctx) {
    const cli = parseArgs(rawArgs, {
      flags: ["--stdout", "--dry-run"],
      defaults: { stdout: false, dryRun: false },
    });
    if (cli.help) {
      printHelp();
      return;
    }
    ctx = resolveDocsContext(container, cli, { commandId: "docs.enrich" });
    ctx.dryRun = cli.dryRun;
    ctx.stdout = cli.stdout;
  }

  const { root, srcRoot, config, type } = ctx;

  // Load analysis
  const analysis = loadFullAnalysis(root);
  if (!analysis) {
    throw new Error("enrich: analysis.json not found. Run 'sennel docs scan' first.");
  }

  // Check for AI agent
  const agent = container.get("agent");
  if (!agent.resolve(ctx.commandId || "docs.enrich")) {
    logger.log("WARN: no agent configured, skipping enrich.");
    logger.log("Set 'defaultAgent' in config.json.");
    return;
  }

  // Get chapter list from preset
  const presetChapterNames = resolveChaptersOrder(type, undefined, root);
  if (presetChapterNames.length === 0) {
    logger.log("WARN: no chapters defined in preset, skipping enrich.");
    return;
  }

  // Build chapter objects with desc (preset defaults + config overrides)
  const presetChapters = presetChapterNames.map((name) => {
    // resolveChaptersOrder returns string[] from preset.json
    // If preset.json has been migrated to object format, the name is already extracted
    return typeof name === "string" ? { chapter: name } : name;
  });
  const chapters = mergeChapters(presetChapters, config?.chapters);

  // Static chapter assignment from {{data}} categories (R4)
  const { docsDir } = ctx;
  const chapterFileNames = chapters.map((c) => c.chapter);
  const categoryToChapter = buildCategoryMapFromDocs(docsDir, chapterFileNames);
  if (categoryToChapter.size > 0) {
    logger.log(`static chapter mapping: ${categoryToChapter.size} categories from {{data}} directives`);
  }

  // Collect entries and filter out already-enriched ones (resume)
  const allEntries = collectEntries(analysis);

  // Apply static chapter assignment to pending entries
  for (const entry of allEntries) {
    if (entry.enriched) continue;
    const staticChapter = categoryToChapter.get(entry.category);
    if (staticChapter) {
      // Set chapter statically; AI will still generate summary/detail
      const items = analysis[entry.category]?.entries;
      if (items && items[entry.index]) {
        items[entry.index].chapter = staticChapter;
      }
    }
  }

  // Filter by docs.exclude patterns
  const docsExclude = config?.docs?.exclude;
  const filtered = filterByDocsExclude(allEntries, docsExclude);
  const excludedCount = allEntries.length - filtered.length;
  if (excludedCount > 0) {
    logger.log(`excluded ${excludedCount} entries by docs.exclude`);
  }

  const pending = filtered.filter((e) => !e.enriched);

  if (pending.length === 0) {
    logger.log("all entries already enriched, skipping.");
    return;
  }

  const skipped = filtered.length - pending.length;
  if (skipped > 0) {
    logger.log(`resuming: ${skipped} already enriched, ${pending.length} remaining`);
  } else {
    logger.log(`enriching ${pending.length} entries with AI...`);
  }

  // Extract essential source for each entry
  const { sourceRoot } = ctx;
  for (const entry of pending) {
    try {
      const filePath = path.resolve(sourceRoot || root, entry.file);
      const code = fs.readFileSync(filePath, "utf8");
      entry.essential = minify(code, entry.file, { mode: "essential" });
    } catch (_) {
      entry.essential = "";
    }
  }

  const promptCharacterLimit = resolvePromptCharacterLimit(config);
  const retryCount = Number(config?.agent?.retryCount) || 0;
  const concurrency = resolveConcurrency(config);
  const envelope = new DocumentationEnrichPromptEnvelope({
    chapters,
    monorepoApps: config.monorepo?.apps,
    lang: config.docs?.defaultLanguage || "en",
    fmtFallback: ENRICH_FMT_FALLBACK,
  });
  const requestLimit = new PromptRequestLimit({ maxCharacters: promptCharacterLimit });
  const builder = new PromptInputBuilder({ envelope, limit: requestLimit });
  pending.forEach((entry, sequence) => builder.add(new DocumentationAnalysisPromptElement({
    id: `analysis:${entry.category}:${entry.index}`,
    sourceRevision: documentationSourceRevision(entry.essential || ""),
    sequence,
    category: entry.category,
    index: entry.index,
    file: entry.file,
    text: entry.essential || "",
  })));
  const collection = builder.build();
  const executionLimit = new PromptExecutionLimit({
    maxRequestCharacters: promptCharacterLimit,
    concurrency,
    maxProtocolRetryCount: retryCount,
  });
  const plan = PromptBatchPlan.create({
    collection,
    envelope,
    limit: requestLimit,
    topology: new LinearPromptBatchTopology(),
    executionLimit,
  });
  logger.log(`${plan.batches.length} batches (character limit: ${promptCharacterLimit}, concurrency: ${concurrency})`);
  const docsAgent = DocumentationAgent.from(agent);
  const executor = new PromptBatchExecutor({ executionLimit });
  const originRangeCounts = new Map();
  for (const batch of plan.batches) {
    for (const element of batch.payloadElements) {
      originRangeCounts.set(element.originId, (originRangeCounts.get(element.originId) || 0) + 1);
    }
  }
  const synthesisCount = [...originRangeCounts.values()].filter((count) => count > 1).length;
  executor.executionBudget.assertCanExecute(plan.batches.length + synthesisCount);
  if (synthesisCount > 0) executor.executionBudget.consumeSynthesisCalls(synthesisCount);
  const callOptions = (request) => ({
    commandId: ctx.commandId || "docs.enrich",
    systemPrompt: request.systemPrompt,
    jsonSchema: request.jsonSchema,
    fmtFallback: request.fmtFallback,
    retryCount,
  });
  const callAgent = (request, _batch, _retryIndex, _attemptContext, providerCallAdmission) => docsAgent.call(request.userPrompt, {
    ...callOptions(request),
    providerCallAdmission,
  });
  const projectInvocation = typeof agent.projectInvocation === "function"
    ? (request) => docsAgent.projectInvocation(request.userPrompt, callOptions(request))
    : undefined;
  const completions = await executor.executeCompletions({
    plan,
    responseContract: new DocumentationEnrichmentResponseContract(),
    callAgent,
    projectInvocation,
  });
  const enrichment = await reduceDocumentationEnrichment({
    completions,
    agent,
    executor,
    limit: requestLimit,
    executionLimit,
    lang: config.docs?.defaultLanguage || "en",
    callOptions,
    projectInvocation,
  });
  const batchEntries = pending.map(({ category, index, file }) => ({ category, index, file }));
  const batchResults = new ConcurrentBatchResult([{
    value: { batch: batchEntries, enrichment }, error: null,
  }]);
  const totalEnriched = new EnrichmentCheckpointCoordinator({
    analysis,
    chapters,
    onWarn: (message) => logger.log(message),
    onCheckpoint: (_checkpoint, count) => {
      if (!ctx.dryRun && !ctx.stdout) {
        const saved = saveAnalysis(root, analysis);
        logger.log(`saved progress (${count} entries) to ${path.relative(root, saved)}`);
      }
    },
  }).apply(batchResults);

  logger.log(`enriched ${totalEnriched} entries in ${plan.batches.length} batches`);

  // Final output
  if (ctx.stdout || ctx.dryRun) {
    process.stdout.write(JSON.stringify(analysis, null, 2) + "\n");
  } else {
    const outputPath = saveAnalysis(root, analysis);
    logger.log(`output: ${path.relative(root, outputPath)}`);
  }
}

export {
  buildEnrichPrompt,
  parseEnrichResponse,
  mergeEnrichment,
  collectEntries,
  filterByDocsExclude,
};

export default class DocsEnrichCommand extends Command {
  static outputMode = "raw";
  async execute(ctx) {
    return runEnrich(ctx.docsCtx, ctx._rawArgs || []);
  }
}

#!/usr/bin/env node
/**
 * sennel/engine/tfill.js
 *
 * {{text}} ディレクティブ専用プロセッサ。
 * テンプレート内の {{text}} を LLM エージェント（claude / codex）で解決し、
 * ディレクティブ直後に説明文を挿入する。
 *
 * Usage:
 *   node sennel/engine/tfill.js --agent claude [--dry-run] [--timeout 60000] [--id <id>]
 */

import fs from "fs";
import path from "path";
import crypto from "crypto";
import { parseDirectives, TEXT_OPEN_RE } from "../lib/directive-parser.js";
import { mapWithConcurrency } from "../lib/concurrency.js";
import { container } from "../../lib/container.js";
import { resolveDocsContext } from "../lib/docs-context.js";
import {
  getEnrichedContext,
  buildTextSystemPrompt,
} from "../lib/text-prompts.js";
import { parseArgs } from "../../lib/cli.js";
import { resolveConcurrency, DEFAULT_CONCURRENCY } from "../../lib/config.js";
import { resolvePromptCharacterLimit } from "../../lib/config.js";
import { Command } from "../../lib/command.js";
import { createLogger } from "../../lib/progress.js";
import { translate } from "../../lib/i18n.js";
import { getChapterFiles, loadFullAnalysis } from "../lib/command-context.js";
import { iterateAnalysisCategories } from "../lib/analysis-entry.js";
import { repairJson } from "../../lib/json-parse.js";
import { EXIT_ERROR } from "../../lib/constants.js";
import {
  DocumentUpdatePlan,
  DocumentUpdateTransaction,
  DocumentValidationResult,
} from "../lib/document-update-plan.js";
import { generateDocumentationDirectives } from "../lib/documentation-text-batching.js";

const logger = createLogger("text");


/**
 * i18n の messages:text.preamblePatterns を RegExp 配列に変換する。
 */
function loadPreamblePatterns() {
  const t = translate();
  const entries = t.raw("messages:text.preamblePatterns");
  if (!Array.isArray(entries) || entries.length === 0) return [];
  return entries.map((e) => new RegExp(e.pattern, e.flags || ""));
}

const ENDTEXT_LINE_RE = /^<!--\s*\{\{\/text\}\}\s*-->$/;

/**
 * Minimum line count in original to trigger shrinkage check.
 * Very short files (< 20 lines) are exempt from shrinkage validation.
 */
const SHRINKAGE_MIN_LINES = 20;

/**
 * If the result has fewer than this ratio of the original lines, reject it.
 * e.g. 0.5 = reject if result is less than 50% of original.
 */
const SHRINKAGE_THRESHOLD = 0.5;

/**
 * バッチ結果の品質を検証する。
 * 行数の大幅縮小や filled 率の低さを検出してリジェクトする。
 *
 * @param {string} original - 元のファイル内容
 * @param {{ text: string, filled: number, skipped: number }} result - バッチ処理結果
 * @param {number} totalDirectives - ファイル内の {{text}} ディレクティブ総数
 * @param {string} fileName - ファイル名（ログ用）
 * @returns {{ ok: boolean, reason?: string }}
 */
function validateBatchResult(original, result, totalDirectives, fileName) {
  const origLines = original.split("\n").length;
  const newLines = result.text.split("\n").length;

  // 縮小検出: 元ファイルが十分長く、結果がしきい値以下に縮小した場合
  if (origLines >= SHRINKAGE_MIN_LINES && newLines < origLines * SHRINKAGE_THRESHOLD) {
    return {
      ok: false,
      reason: `content shrinkage detected: ${origLines} → ${newLines} lines (${Math.round(newLines / origLines * 100)}%). Original preserved.`,
    };
  }

  // filled 率: 複数ディレクティブがあるのに全く埋まらなかった場合
  if (totalDirectives > 0 && result.filled === 0) {
    return {
      ok: false,
      reason: `0/${totalDirectives} directives filled. No file update was published.`,
    };
  }

  // filled 率: 半数以上が埋まらなかった場合は警告（ただし書き込みは許可）
  if (totalDirectives > 1 && result.filled < totalDirectives * SHRINKAGE_THRESHOLD) {
    logger.log(`WARN ${fileName}: only ${result.filled}/${totalDirectives} directives filled.`);
  }

  return { ok: true };
}

// ---------------------------------------------------------------------------
// バッチモード：ファイル単位で全ディレクティブをbounded map/reduceで処理
// ---------------------------------------------------------------------------

/**
 * テンプレートファイルの {{text}} ディレクティブ後にある既存生成コンテンツを
 * 除去してクリーンなテンプレート状態に戻す。
 * processTemplate の endLine 計算と同じ境界ロジックを使用する。
 */
function stripFillContent(text, directiveId) {
  const lines = text.split("\n");
  const selectedLines = directiveId === undefined
    ? null
    : new Set(parseDirectives(text)
      .filter((directive) => directive.type === "text" && directive.params?.id === directiveId)
      .map((directive) => directive.line));
  const result = [];
  let i = 0;
  while (i < lines.length) {
    result.push(lines[i]);
    if (TEXT_OPEN_RE.test(lines[i].trim()) && (selectedLines === null || selectedLines.has(i))) {
      i++;
      // {{/text}} 終了タグまでスキップ
      while (i < lines.length && !ENDTEXT_LINE_RE.test(lines[i].trim())) {
        i++;
      }
      // 終了タグ自体は結果に含める
      if (i < lines.length) {
        result.push(lines[i]);
        i++;
      }
    } else {
      i++;
    }
  }
  return result.join("\n");
}

/**
 * バッチ結果のファイルで埋められたディレクティブ数をカウントする。
 * ディレクティブ行の次の非空行が ## / <!-- @ でなければ filled と判定する。
 */
function countFilledInBatch(fileText) {
  const lines = fileText.split("\n");
  let filled = 0;
  for (let i = 0; i < lines.length; i++) {
    if (TEXT_OPEN_RE.test(lines[i].trim())) {
      // 開始タグと終了タグの間に非空行があれば filled
      let hasContent = false;
      for (let j = i + 1; j < lines.length; j++) {
        if (ENDTEXT_LINE_RE.test(lines[j].trim())) break;
        if (lines[j].trim() !== "") { hasContent = true; break; }
      }
      if (hasContent) filled++;
    }
  }
  return filled;
}

/**
 * JSON レスポンスをパースする。コードフェンスがあれば除去する。
 *
 * @param {string} response - AI のレスポンス
 * @returns {Object|null} パース結果、失敗時は null
 */
function parseBatchJsonResponse(response) {
  try {
    return JSON.parse(repairJson(response));
  } catch (_) {
    return null;
  }
}

function directiveBatchId(directive, index) {
  return directive.params?.id || `d${index}`;
}

function resolveBatchContextOptions(srcRoot, retryCount) {
  if (retryCount === undefined && typeof srcRoot === "number") {
    return { srcRoot: undefined, retryCount: srcRoot };
  }
  return { srcRoot, retryCount };
}

/**
 * JSON レスポンスを元のファイルのディレクティブ位置に挿入する。
 *
 * @param {string} text - 元のファイル内容（stripFillContent 済み）
 * @param {{ type: string, line: number, endLine: number, params?: Object, prompt: string }[]} textFills - ディレクティブ一覧
 * @param {Object} jsonData - パース済み JSON（id → テキスト）
 * @returns {{ text: string, filled: number, skipped: number }}
 */
function applyBatchJsonToFile(text, textFills, jsonData) {
  const lines = text.split("\n");
  let filled = 0;
  let skipped = 0;

  // 逆順で挿入（行番号のずれを防ぐ）
  for (let i = textFills.length - 1; i >= 0; i--) {
    const d = textFills[i];
    const id = directiveBatchId(d, i);
    let generated = jsonData[id];

    if (!generated) {
      skipped++;
      continue;
    }

    const endLine = d.endLine;
    if (endLine < 0) {
      skipped++;
      continue;
    }

    if (d.params?.maxLines) generated = generated.split("\n").slice(0, d.params.maxLines).join("\n");
    if (d.params?.maxChars) generated = generated.slice(0, d.params.maxChars);
    const content = [d.params?.header, generated, d.params?.footer].filter(Boolean).join("\n");
    const endTag = lines[endLine];
    const newLines = [d.raw, "\n" + content, endTag];
    lines.splice(d.line, endLine - d.line + 1, ...newLines);
    filled++;
  }

  let result = lines.join("\n");
  if (!result.endsWith("\n")) result += "\n";
  return { text: result, filled, skipped };
}

/**
 * ファイル内のすべての {{text}} ディレクティブをbounded LLM batchesで処理する。
 * AI には JSON 形式でディレクティブごとのテキストを返させ、
 * コード側で元ファイルの該当位置に挿入する。
 *
 * @returns {{ text: string, filled: number, skipped: number }}
 */
async function processTemplateFileBatch(text, analysis, fileName, agent, dryRun, _preamblePatterns, systemPrompt, _filterId, concurrency, lang, srcRoot, retryCount, promptCharacterLimit) {
  const batchOptions = resolveBatchContextOptions(srcRoot, retryCount);
  // cleanText を先に計算してから parseDirectives を呼ぶ。
  // stripFillContent は既存コンテンツを除去するため行数が変わる。
  // parseDirectives の行番号は applyBatchJsonToFile に渡す text と一致させる必要がある。
  const cleanText = stripFillContent(text, _filterId);
  const directives = parseDirectives(cleanText);
  let textFills = directives.filter((d) => d.type === "text");
  if (_filterId) textFills = textFills.filter((directive) => directive.params?.id === _filterId);

  if (textFills.length === 0) return { text, filled: 0, skipped: 0 };

  // Determine the deepest mode across all directives in this file
  const hasDeep = textFills.some((d) => d.params?.mode === "deep");
  const batchMode = hasDeep ? "deep" : "light";
  const enriched = getEnrichedContext(analysis, fileName, batchMode, batchOptions.srcRoot);
  // The complete analysis is canonical source evidence. Directive-category
  // projections can legitimately be empty (for example, project structure),
  // so using one here would make a bounded batch complete but ungrounded.
  const contextData = analysis;

  if (dryRun) {
    console.log(`[text] DRY-RUN batch ${fileName}: ${textFills.length} directive(s)`);
    return { text, filled: 0, skipped: textFills.length };
  }

  logger.verbose(`Batch ${fileName}: ${textFills.length} directive(s)`);
  const jsonData = await generateDocumentationDirectives({
    cleanText,
    enrichedContext: enriched,
    analysisContext: contextData,
    textFills,
    fileName,
    systemPrompt,
    lang,
    agent,
    executionWorkDir: batchOptions.srcRoot,
    retryCount: batchOptions.retryCount || 0,
    maxCharacters: promptCharacterLimit,
    concurrency: concurrency || DEFAULT_CONCURRENCY,
  });

  const applied = applyBatchJsonToFile(cleanText, textFills, jsonData);
  logger.verbose(`Batch DONE ${fileName}: ${applied.filled}/${textFills.length} filled`);

  return applied;
}

// ---------------------------------------------------------------------------
// テンプレート処理
// ---------------------------------------------------------------------------

/**
 * 1 ファイルの {{text}} ディレクティブをすべて処理する。
 *
 * @param {string} text        - テンプレート全文
 * @param {Object} analysis    - analysis.json
 * @param {string} fileName    - ファイル名
 * @param {Object} agent       - Agent service
 * @param {boolean} dryRun     - dry-run モード
 * @returns {{ text: string, filled: number, skipped: number }}
 */
async function processTemplate(text, analysis, fileName, agent, dryRun, preamblePatterns, systemPrompt, filterId, concurrency, lang, srcRoot, retryCount, promptCharacterLimit) {
  return processTemplateFileBatch(
    text, analysis, fileName, agent, dryRun, preamblePatterns, systemPrompt,
    filterId, concurrency, lang, srcRoot, retryCount, promptCharacterLimit,
  );
}

// ---------------------------------------------------------------------------
// textFillFromAnalysis (エクスポート用: forge.js などから呼び出し可能)
// ---------------------------------------------------------------------------
/**
 * ファイル内の全 {{text}} ディレクティブが埋まっているかチェックする。
 * 1 つでも空のディレクティブがあれば false を返す。
 *
 * @param {string} text - ファイル内容
 * @returns {boolean} 全ディレクティブが埋まっている場合 true
 */
function allTextDirectivesFilled(text) {
  const directives = parseDirectives(text);
  const textFills = directives.filter((d) => d.type === "text");
  if (textFills.length === 0) return true;

  const lines = text.split("\n");
  for (const d of textFills) {
    if (d.endLine < 0) return false;
    let hasContent = false;
    for (let j = d.line + 1; j < d.endLine; j++) {
      if (lines[j].trim() !== "") { hasContent = true; break; }
    }
    if (!hasContent) return false;
  }
  return true;
}

/**
 * @param {string} root       - リポジトリルート
 * @param {Object} analysis   - analysis.json データ
 * @param {string} commandId  - コマンドID (docs.text)
 * @param {string} [srcRoot]  - ソースルート
 * @param {Object} [opts]     - オプション
 * @param {string[]} [opts.files] - 処理対象ファイル名の配列。指定時はそのファイルのみ処理する
 * @returns {{ filled: number, skipped: number, files: string[] }}
 */
export async function textFillFromAnalysis(root, analysis, commandId, srcRoot, opts) {
  if (!analysis) return { filled: 0, skipped: 0, files: [] };

  const cfg = container.get("config");
  const agent = container.get("agent");
  if (!agent.resolve(commandId || "docs.text")) {
    throw new Error("No agent configured. Set 'agent.default' in config.json or run 'sennel setup'.");
  }
  const preamblePatterns = loadPreamblePatterns();
  const documentStyle = cfg?.docs?.style;
  const lang = cfg?.docs?.defaultLanguage;
  const systemPrompt = buildTextSystemPrompt(documentStyle, lang);
  const type = cfg?.type || undefined;
  const concurrency = resolveConcurrency(cfg);
  const promptCharacterLimit = resolvePromptCharacterLimit(cfg);
  const docsDir = path.join(root, "docs");
  const resolvedSrcRoot = srcRoot || root;

  const targetFiles = opts?.files || getChapterFiles(docsDir, { type, configChapters: cfg?.chapters, projectRoot: root });

  const changedFiles = [];
  const plans = [];
  let totalFilled = 0;
  let totalSkipped = 0;

  // Batch mode: file-level parallelism; each file owns a bounded prompt plan.
  const fileResults = await mapWithConcurrency(targetFiles, concurrency, async (file) => {
    const filePath = path.join(docsDir, file);
    const originalBytes = fs.readFileSync(filePath);
    const original = originalBytes.toString("utf8");
    const retryCount = Number(cfg?.agent?.retryCount) || 0;
    const result = await processTemplateFileBatch(original, analysis, file, agent, false, preamblePatterns, systemPrompt, undefined, concurrency, lang, resolvedSrcRoot, retryCount, promptCharacterLimit);
    return { file, filePath, originalBytes, original, result };
  });
  fileResults.throwIfErrors();

  for (let i = 0; i < fileResults.length; i++) {
    const entry = fileResults[i];
    const { file, filePath, originalBytes, original, result } = entry.value;
    if (!result) continue;

    const totalDirectives = parseDirectives(original).filter((d) => d.type === "text").length;
    const validation = validateBatchResult(original, result, totalDirectives, file);
    const validationResult = validation.ok
      ? DocumentValidationResult.accepted()
      : DocumentValidationResult.rejected(validation.reason);
    plans.push(new DocumentUpdatePlan({
      filePath,
      originalBytes,
      proposedBytes: Buffer.from(result.text),
      validationResult,
    }));

    totalFilled += result.filled;
    totalSkipped += result.skipped;

    if (result.filled > 0) {
      changedFiles.push(file);
    }
  }

  new DocumentUpdateTransaction(plans, { faultInjector: opts?.faultInjector }).commit();

  return { filled: totalFilled, skipped: totalSkipped, files: changedFiles, errors: [] };
}

// ---------------------------------------------------------------------------
// Diff-based chapter detection
// ---------------------------------------------------------------------------

/**
 * Compare each entry's stored hash against the current source file's hash.
 * Returns a Set of chapter names that need regeneration, or null if
 * diff detection is not possible (e.g., no enriched entries with chapter field).
 */
function detectChangedChapters(analysis, srcRoot) {
  const chapters = new Set();
  let hasChapterField = false;

  for (const [, catData] of iterateAnalysisCategories(analysis)) {
    for (const entry of catData.entries) {
      if (!entry.chapter) continue;
      hasChapterField = true;

      if (!entry.file || !entry.hash) {
        chapters.add(entry.chapter);
        continue;
      }

      const absPath = path.join(srcRoot, entry.file);
      if (!fs.existsSync(absPath)) {
        chapters.add(entry.chapter);
        continue;
      }

      const currentHash = crypto.createHash("md5")
        .update(fs.readFileSync(absPath, "utf8"))
        .digest("hex");
      if (entry.hash !== currentHash) {
        chapters.add(entry.chapter);
      }
    }
  }

  return hasChapterField ? chapters : null;
}

// ---------------------------------------------------------------------------
// CLI メイン
// ---------------------------------------------------------------------------
async function runText(ctx, rawArgs) {
  // CLI モード
  if (!ctx) {
    const cli = parseArgs(rawArgs, {
      flags: ["--dry-run", "--per-directive", "--force"],
      options: ["--id", "--lang", "--docs-dir", "--files"],
      defaults: { dryRun: false, perDirective: false, force: false, id: "", lang: "", docsDir: "", files: "" },
    });
    if (cli.help) {
      const t = translate();
      const h = t.raw("ui:help.cmdHelp.text");
      const o = h.options;
      console.log([
        h.usage, "", "Options:",
        `  ${o.id}`, `  ${o.dryRun}`, `  ${o.perDirective}`,
        `  ${o.help}`,
      ].join("\n"));
      return;
    }

    ctx = resolveDocsContext(container, cli, { commandId: "docs.text" });
    ctx.dryRun = cli.dryRun;
    ctx.perDirective = cli.perDirective;
    ctx.force = cli.force;
    ctx.id = cli.id;
    if (cli.files) ctx.files = cli.files.split(",").map((f) => f.trim()).filter(Boolean);
  }

  const { root, srcRoot, config: cfg, docsDir } = ctx;

  const analysis = loadFullAnalysis(root) || {};
  if (Object.keys(analysis).length === 0) {
    logger.log("WARN: analysis.json not found. Proceeding with empty analysis context.");
  }
  const agent = ctx.agent || container.get("agent");
  if (!agent.resolve(ctx.commandId || "docs.text")) {
    throw new Error("No agent configured. Set 'agent.default' in config.json or run 'sennel setup'.");
  }

  const preamblePatterns = loadPreamblePatterns();
  const documentStyle = cfg.docs?.style;
  const lang = ctx.outputLang;
  const systemPrompt = buildTextSystemPrompt(documentStyle, lang);
  const concurrency = resolveConcurrency(cfg);
  const promptCharacterLimit = resolvePromptCharacterLimit(cfg);

  // File selection: use ctx.files if provided, otherwise get all chapter files and strip
  let targetFiles;
  if (ctx.files) {
    targetFiles = ctx.files;
  } else {
    targetFiles = getChapterFiles(docsDir, { type: ctx.type, configChapters: cfg.chapters, projectRoot: root });

    // Diff-based chapter filtering: skip chapters whose entries are unchanged
    if (!ctx.force) {
      const changedChapters = detectChangedChapters(analysis, srcRoot);
      if (changedChapters) {
        if (changedChapters.size === 0) {
          // No source changes, but check for unfilled text directives
          const unfilledFiles = targetFiles.filter((f) => {
            const content = fs.readFileSync(path.join(docsDir, f), "utf8");
            return !allTextDirectivesFilled(content);
          });
          if (unfilledFiles.length === 0) {
            logger.log("No source changes detected. Use --force to regenerate all chapters.");
            return { errors: [] };
          }
          targetFiles = unfilledFiles;
          logger.log(`No source changes, but ${unfilledFiles.length} file(s) have unfilled text directives.`);
        } else {
          const before = targetFiles.length;
          targetFiles = targetFiles.filter((f) => {
            const chapterName = f.replace(/\.md$/, "");
            return changedChapters.has(chapterName);
          });
          logger.log(`Diff: ${changedChapters.size} chapter(s) changed [${[...changedChapters].join(", ")}], processing ${targetFiles.length}/${before} file(s).`);
        }
      }
    }

  }

  let totalFilled = 0;
  let totalSkipped = 0;
  const changedFiles = new Set();

  // --id narrows the scoped batch plan to one directive.
  if (ctx.id) {
    ctx.perDirective = true;
    logger.verbose(`--id=${ctx.id}: per-directive mode forced.`);
  }

  const retryCount = Number(cfg?.agent?.retryCount) || 0;
  const processFn = processTemplateFileBatch;
  if (!ctx.perDirective) {
    logger.verbose(`Mode: bounded batch (${targetFiles.length} file(s), concurrency=${concurrency}).`);
  }

  // Prepare file entries (filter for --id before parallel dispatch)
  const fileEntries = [];
  for (const file of targetFiles) {
    const filePath = path.join(docsDir, file);
    const originalBytes = fs.readFileSync(filePath);
    const original = originalBytes.toString("utf8");

    if (ctx.id) {
      const directives = parseDirectives(original);
      const hasId = directives.some((d) => d.type === "text" && d.params?.id === ctx.id);
      if (!hasId) continue;
    }

    fileEntries.push({ file, filePath, originalBytes, original });
  }

  // File-level concurrency is independent from each file's bounded prompt plan.
  const fileConcurrency = concurrency;
  const plans = [];
  const fileResults = await mapWithConcurrency(fileEntries, fileConcurrency, async (entry) => {
    const { file, original } = entry;
    logger.verbose(`start: ${file}`);
    const result = await processFn(original, analysis, file, agent, ctx.dryRun, preamblePatterns, systemPrompt, ctx.id || undefined, concurrency, lang, srcRoot, retryCount, promptCharacterLimit);
    logger.verbose(`done: ${file}`);
    return { ...entry, result };
  });
  fileResults.throwIfErrors();

  // Apply results
  for (let i = 0; i < fileEntries.length; i++) {
    const resultEntry = fileResults[i];
    const { file, filePath, originalBytes, original, result } = resultEntry.value;
    if (!result) continue;

    // バッチモードの場合は結果を検証
    let validationResult = DocumentValidationResult.accepted();
    if (!ctx.perDirective && !ctx.dryRun) {
      const totalDirectives = parseDirectives(original).filter((d) => d.type === "text").length;
      const validation = validateBatchResult(original, result, totalDirectives, file);
      if (!validation.ok) {
        logger.log(`REJECTED ${file}: ${validation.reason}`);
        validationResult = DocumentValidationResult.rejected(validation.reason);
      }
    }

    totalFilled += result.filled;
    totalSkipped += result.skipped;

    if (!ctx.dryRun && (result.filled > 0 || !validationResult.ok)) {
      plans.push(new DocumentUpdatePlan({
        filePath,
        originalBytes,
        proposedBytes: Buffer.from(result.text),
        validationResult,
      }));
    }

    if (result.filled > 0) {
      changedFiles.add(file);
    }
  }

  if (!ctx.dryRun) {
    new DocumentUpdateTransaction(plans, { faultInjector: ctx.faultInjector }).commit();
    for (const file of changedFiles) logger.verbose(`UPDATED: ${file}`);
  }

  logger.log(`Done. ${changedFiles.size} file(s) updated. filled: ${totalFilled}, skipped: ${totalSkipped}.`);
  return { errors: [] };
}

export { stripFillContent, countFilledInBatch, processTemplateFileBatch, processTemplate, allTextDirectivesFilled, validateBatchResult, parseBatchJsonResponse, applyBatchJsonToFile, detectChangedChapters };

export default class DocsTextCommand extends Command {
  static outputMode = "raw";
  async execute(ctx) {
    const result = await runText(ctx.docsCtx, ctx._rawArgs || []);
    if (result?.errors?.length > 0) {
      const err = new Error(`${result.errors.length} file(s) failed: ${result.errors.join(", ")}`);
      err.exitCode = EXIT_ERROR;
      err.data = result;
      err.agentError = true;
      throw err;
    }
    return result;
  }
}

#!/usr/bin/env node
/**
 * src/flow.js
 *
 * Flow dispatcher. Top-level command routing (query / prepare / resume / get /
 * set / run) feeds the shared dispatcher (src/lib/dispatcher.js), which handles
 * argument parsing, lifecycle hooks, and envelope output uniformly across
 * every domain.
 */

import { EXIT_ERROR } from "./lib/constants.js";
import { container, initContainer } from "./lib/container.js";
import { buildFlowCommandHookContext } from "./flow/lib/flow-context.js";
import { coreCommandRegistry } from "./lib/command-registry.js";
import { dispatch } from "./lib/dispatcher.js";

const args = process.argv.slice(2);
if (args[0] === "query") {
  const { bootstrapFlowQueryCli } = await import("./flow/query.js");
  process.exit(await bootstrapFlowQueryCli(args.slice(1)));
}
initContainer({
  flowAttribution: args[0] === "run" && args[1] === "abort" ? "none" : "ambient",
});

const group = args[0];
const rest = args.slice(1);
const flowDefinition = coreCommandRegistry.find(["flow"]);
const flowCommandSuggestionByGroup = {
  status: "sennel flow get status",
};

function isolatedArtifactHookContext(container, flowResolutionError = null) {
  const paths = container.get("paths");
  const mainRoot = container.get("mainRoot");
  return {
    root: mainRoot,
    mainRoot,
    config: container.get("config"),
    paths,
    flowManager: container.get("flowManager"),
    flowState: null,
    preparingFlowState: null,
    specId: null,
    specLocation: null,
    executionRoot: paths.root,
    flowResolutionError,
  };
}

function artifactContextReadFailure(cause) {
  const error = new Error(cause?.message || String(cause), { cause });
  error.code = "ARTIFACT_VIEW_READ_FAILED";
  return error;
}

if (!group || group === "-h" || group === "--help") {
  console.log(flowDefinition.renderHelp());
  if (!group) process.exit(EXIT_ERROR);
  process.exit(0);
}

async function run(entry, argv, envelopeType, envelopeKey, helpPathOverride) {
  const resolvedEntry = entry?.helpPath
    ? entry
    : { ...entry, helpPath: helpPathOverride || `sennel flow ${envelopeType} ${envelopeKey} --help` };
  // Artifact views are read-only apart from their Version-local view cache.
  // A dispatcher runtime log would create an unrelated activity artifact and
  // violate that boundary, so this command deliberately has no runtime log.
  const runtimeLog = !(group === "get" && (envelopeKey === "runtime-log" || envelopeKey === "artifact"));
  await dispatch({
    container,
    entry: resolvedEntry,
    argv,
    envelopeType,
    envelopeKey,
    runtimeLog,
    buildHookCtx: (c, input = {}) => {
      // A command may own an exact, non-active target selector. In that case
      // the dispatcher must not discover or guard an ambient Flow before the
      // command has validated the selector. This generic escape hatch keeps
      // completed Version reads isolated from unrelated active authority.
      if (typeof resolvedEntry.skipAmbientFlowContext === "function" && resolvedEntry.skipAmbientFlowContext(input) === true) {
        return isolatedArtifactHookContext(c);
      }
      try {
        return buildFlowCommandHookContext(c, resolvedEntry, input);
      } catch (error) {
        if (group === "get" && envelopeKey === "artifact") {
          return isolatedArtifactHookContext(c, artifactContextReadFailure(error));
        }
        throw error;
      }
    },
  });
}

async function dispatchFlow() {
  // Top-level: resume
  if (group === "resume") {
    await run(flowDefinition.find(["resume"]), rest, "run", "resume");
    return;
  }

  // Top-level: prepare
  if (group === "prepare") {
    await run(flowDefinition.find(["prepare"]), rest, "run", "prepare-spec");
    return;
  }

  // Group commands: get / set / run
  const commands = flowDefinition.find([group]);
  if (!commands || commands.command || commands.subcommands.size === 0) {
    console.error(`sennel flow: unknown command '${group}'`);
    const suggestion = flowCommandSuggestionByGroup[group];
    if (suggestion) {
      console.error(`Did you mean: ${suggestion}`);
    }
    console.error("Run: sennel flow --help");
    process.exit(EXIT_ERROR);
  }

  const cmd = rest[0];
  const cmdArgs = rest.slice(1);

  if (!cmd || cmd === "-h" || cmd === "--help") {
    console.log(commands.renderHelp());
    if (!cmd) process.exit(EXIT_ERROR);
    process.exit(0);
  }

  const entry = commands.find([cmd]);
  if (!entry?.command) {
    console.error(`sennel flow ${group}: unknown key '${cmd}'`);
    console.error(`Run: sennel flow ${group} --help`);
    process.exit(EXIT_ERROR);
  }

  await run(entry, cmdArgs, group, cmd);
}

await dispatchFlow();

/**
 * src/flow/lib/flow-context.js
 *
 * Pure function that assembles flow-specific context fields from the shared
 * dependency container. Replaces the former resolveCtx() in src/flow.js.
 *
 * Flow state and artifacts always live under the main repository's configured
 * spec root. `root`/`repositoryRoot` identify that artifact authority, while
 * `executionRoot` identifies the checkout where source commands run.
 */

import { FlowTargetExpectation } from "../../lib/flow-target-guard.js";
import { WorktreeFlowProvenance } from "../../lib/worktree-flow-binding.js";
import { FlowSpecLocation, flowSpecRootFromConfig } from "../../lib/flow-workspace.js";
import { FLOW_DISPATCH_INVOCATION_ID_ENV } from "./dispatch-invocation.js";

const MISSING_PREPARING_FLOW_STATE = Object.freeze({});
const DISPATCH_INVOCATION_ENV = FLOW_DISPATCH_INVOCATION_ID_ENV;

function dispatchInvocationIdFromEnvironment() {
  const value = process.env[DISPATCH_INVOCATION_ENV];
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function resolveTargetSelection(expectation) {
  const selectRunId = expectation.effectiveRunId;
  const selectSpecId = expectation.effectiveSpecId;
  const selectIssue = expectation.effectiveIssue;
  const selectNoIssue = expectation.expectsNoIssue;
  if (selectRunId == null && selectSpecId == null && selectIssue == null && !selectNoIssue) return null;
  return { selectRunId, selectSpecId, selectIssue, selectNoIssue };
}

function preparingRunIdSelection(input = {}) {
  const runId = input.runId ?? null;
  if (typeof runId !== "string") return null;
  const trimmed = runId.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function targetExpectationInput(options = {}) {
  const input = options.input || {};
  if (
    options.positionalRunIdTarget === true
    && typeof input.runId === "string"
    && input.runId.trim() !== ""
  ) {
    return { expectRunId: input.runId };
  }
  return input;
}

export function flowTargetExpectation(options = {}) {
  return new FlowTargetExpectation(targetExpectationInput(options));
}

function preparingAuthorityForRunId(baseFlowManager, mainRoot, paths, runId) {
  if (!runId || typeof baseFlowManager.loadPreparingFlow !== "function") return null;
  const state = baseFlowManager.loadPreparingFlow(runId);
  const authorityRoot = paths.root || mainRoot;
  return {
    flowManager: baseFlowManager.forRoot(authorityRoot),
    flowState: null,
    preparingFlowState: state || MISSING_PREPARING_FLOW_STATE,
    authorityRoot,
    flowResolutionError: null,
  };
}

function boundWorktreeAuthority(container, baseFlowManager, mainRoot, paths, expectation) {
  if (!container.get("inWorktree")) return null;
  if (baseFlowManager.usesWorktreeFlowBinding() === false) return null;
  let identity;
  try {
    identity = baseFlowManager.resolveWorktreeBinding(expectation);
  } catch (error) {
    return {
      flowManager: baseFlowManager,
      flowState: null,
      preparingFlowState: null,
      authorityRoot: null,
      flowResolutionError: error,
    };
  }
  const flowManager = baseFlowManager.forRoot(paths.root, { specId: identity.specId });
  const flowState = flowManager.load(identity.specId);
  return {
    flowManager,
    flowState,
    preparingFlowState: null,
    authorityRoot: paths.root,
    flowResolutionError: null,
    worktreeFlowProvenance: new WorktreeFlowProvenance(identity, mainRoot),
  };
}

function recoveryTargetExpectation(container, baseFlowManager, expectation) {
  if (!container.get("inWorktree") || baseFlowManager.usesWorktreeFlowBinding() === false) {
    return expectation;
  }
  const identity = baseFlowManager.resolveWorktreeBinding(expectation);
  return new FlowTargetExpectation({
    expectRunId: identity.runId,
    expectSpec: identity.specId,
    ...(identity.issue === null ? { expectNoIssue: true } : { expectIssue: identity.issue }),
  });
}

function resolveRecoveryAuthorityFlowState(container, baseFlowManager, options = {}) {
  let expectation = options.targetExpectation;
  try {
    expectation = recoveryTargetExpectation(container, baseFlowManager, expectation);
    const target = baseFlowManager.resolveFlowRecoveryTarget(expectation);
    const flowManager = baseFlowManager.forRoot(target.authorityRoot, { specId: target.specId });
    return {
      flowManager,
      flowState: target.state,
      preparingFlowState: null,
      authorityRoot: target.authorityRoot,
      flowResolutionError: null,
    };
  } catch (error) {
    if (!options.allowMissingActive && !options.captureTargetResolutionError) throw error;
    return {
      flowManager: baseFlowManager,
      flowState: null,
      preparingFlowState: null,
      authorityRoot: null,
      flowResolutionError: error,
    };
  }
}

function resolveAuthorityFlowState(container, baseFlowManager, mainRoot, options = {}) {
  const paths = container.get("paths");
  const targetExpectation = options.targetExpectation instanceof FlowTargetExpectation
    ? options.targetExpectation
    : flowTargetExpectation(options);
  if (options.recoveryTargetResolution === true) {
    return resolveRecoveryAuthorityFlowState(
      container,
      baseFlowManager,
      { ...options, targetExpectation },
    );
  }
  const worktreeAuthority = boundWorktreeAuthority(
    container,
    baseFlowManager,
    mainRoot,
    paths,
    targetExpectation,
  );
  if (worktreeAuthority) return worktreeAuthority;
  const preparingAuthority = options.preparingRunIdSelection === false
    ? null
    : preparingAuthorityForRunId(
      baseFlowManager,
      mainRoot,
      paths,
      preparingRunIdSelection(options.input),
    );
  if (preparingAuthority) return preparingAuthority;

  const selection = resolveTargetSelection(targetExpectation);
  // Any parsed target guard is an exact authority selection, including
  // ordinary commands such as `set note`.  Resolving the unscoped active
  // manager first is invalid when concurrent Flows exist and lets hook setup
  // observe a different Flow than the command itself.
  if (selection) {
    let target;
    try {
      const resolver = options.mismatchTargetResolution === true
        ? baseFlowManager.resolveExplicitFlowTargetForRead.bind(baseFlowManager)
        : baseFlowManager.resolveExplicitFlowTarget.bind(baseFlowManager);
      target = resolver(targetExpectation);
    } catch (error) {
      if (!options.allowMissingActive && !options.captureTargetResolutionError) throw error;
      return {
        flowManager: baseFlowManager,
        flowState: null,
        preparingFlowState: null,
        authorityRoot: null,
        flowResolutionError: error,
      };
    }
    const flowManager = baseFlowManager.forRoot(
      target.authorityRoot,
      target.specId ? { specId: target.specId } : {},
    );
    return {
      flowManager,
      flowState: target.preparing ? null : target.state,
      preparingFlowState: target.preparing ? target.state : null,
      authorityRoot: target.authorityRoot,
      flowResolutionError: null,
    };
  }
  const cwdState = baseFlowManager.load();
  if (!cwdState) {
    let resolved = null;
    try {
      resolved = typeof baseFlowManager.resolveActiveFlow === "function"
        ? baseFlowManager.resolveActiveFlow(null, selection || {})
        : null;
    } catch (err) {
      if (!options.allowMissingActive) throw err;
      return { flowManager: baseFlowManager, flowState: null, authorityRoot: null, flowResolutionError: err };
    }
    if (resolved) {
      const activeRoot = resolved.worktreePath || paths.root;
      const activeFm = resolved.worktreePath
        ? baseFlowManager.forRoot(resolved.worktreePath, { specId: resolved.specId })
        : baseFlowManager.forRoot(paths.root, { specId: resolved.specId });
      return { flowManager: activeFm, flowState: resolved.state, authorityRoot: activeRoot };
    }
    return { flowManager: baseFlowManager, flowState: null, authorityRoot: null, flowResolutionError: null };
  }

  return { flowManager: baseFlowManager, flowState: cwdState, authorityRoot: paths.root, flowResolutionError: null };
}

export function resolveFlowContext(container, options = {}) {
  const paths = container.get("paths");
  const baseFlowManager = container.get("flowManager");
  const mainRoot = container.get("mainRoot");
  const targetExpectation = options.targetExpectation instanceof FlowTargetExpectation
    ? options.targetExpectation
    : flowTargetExpectation(options);
  const {
    flowManager,
    flowState,
    preparingFlowState = null,
    authorityRoot,
    flowResolutionError,
    worktreeFlowProvenance = null,
  } = resolveAuthorityFlowState(
    container,
    baseFlowManager,
    mainRoot,
    { ...options, targetExpectation },
  );
  const executionRoot = authorityRoot || paths.root;
  const config = container.get("config");
  const specRoot = container.has("flowSpecRoot")
    ? container.get("flowSpecRoot")
    : flowSpecRootFromConfig(config);
  const specLocation = flowState
    ? (typeof flowManager.specLocation === "function"
        ? flowManager.specLocation(flowState.specId)
        : new FlowSpecLocation({ repositoryRoot: mainRoot, specRoot, specId: flowState.specId }))
    : null;
  return {
    root: mainRoot,
    mainRoot,
    config,
    paths,
    flowManager,
    flowState,
    preparingFlowState,
    specId: flowState?.specId ?? null,
    specLocation,
    specRoot,
    repositoryRoot: mainRoot,
    artifactRoot: mainRoot,
    executionRoot,
    inWorktree: container.get("inWorktree"),
    authorityRoot,
    flowResolutionError,
    worktreeFlowProvenance,
    targetExpectation,
    dispatchInvocationId: dispatchInvocationIdFromEnvironment(),
  };
}

/**
 * Build the context consumed by the shared command dispatcher and registry
 * hooks.  Keeping this beside FlowCommand's resolver prevents in-process
 * dispatcher execution from drifting from the public `sennel flow` entrypoint.
 */
export function buildFlowCommandHookContext(container, entry, input = {}) {
  const targetInput = entry.specOptionAsTarget === true
    && input.expectSpec == null
    && input.spec != null
    ? { ...input, expectSpec: input.spec }
    : input;
  return resolveFlowContext(container, {
    allowMissingActive: entry.requiresFlow === false,
    captureTargetResolutionError: true,
    explicitTargetResolution: entry.explicitTargetResolution === true,
    mismatchTargetResolution: entry.mismatchTargetResolution === true,
    recoveryTargetResolution: entry.recoveryTargetResolution === true,
    positionalRunIdTarget: entry.positionalRunIdTarget === true,
    preparingRunIdSelection: entry.preparingRunIdSelection !== false,
    input: targetInput,
  });
}

