// ---------------------------------------------------------------------------
// Config validation
// ---------------------------------------------------------------------------

/**
 * Validate a config object against the schema.
 * Throws on any validation failure.
 *
 * @param {*} raw - Parsed config object
 * @returns {import("./types.js").ProjectConfig} Validated config
 */
const MISSING_TYPE_ERROR = "type: required field is missing";

export function validate(raw, options = {}) {
  if (!raw || typeof raw !== "object") {
    throw new Error("config must be a non-null object");
  }

  const errors = validateSchema(raw, options.schema || CONFIG_SCHEMA);
  if (options.allowMissingType === true) {
    const index = errors.indexOf(MISSING_TYPE_ERROR);
    if (index !== -1) errors.splice(index, 1);
  }

  // Cross-field validation: defaultLanguage must be in languages
  if (Array.isArray(raw.docs?.languages) && typeof raw.docs?.defaultLanguage === "string") {
    if (!raw.docs.languages.includes(raw.docs.defaultLanguage)) {
      errors.push("'docs.defaultLanguage' must be one of 'docs.languages'");
    }
  }

  // Cross-field validation: profile provider references must be valid
  const agentProfiles = raw.agent
    ? { ...defaultAgentProfiles(), ...(raw.agent.profiles || {}) }
    : {};
  const registry = raw.agent ? new ProviderRegistry(raw.agent?.providers || {}) : null;

  if (Object.hasOwn(raw.agent || {}, "batchTokenLimit")) {
    errors.push("'agent.batchTokenLimit': unknown field; use 'agent.promptCharacterLimit'");
  }

  if (raw.agent?.profiles) {
    for (const [profileName, profile] of Object.entries(raw.agent.profiles)) {
      if (typeof profile !== "object" || profile == null) continue;
      for (const [commandId, providerKey] of Object.entries(profile)) {
        if (typeof providerKey === "string" && !registry.hasProfile(providerKey)) {
          errors.push(`'agent.profiles.${profileName}.${commandId}': unknown provider "${providerKey}"`);
        }
      }
    }
  }

  // Cross-field validation: useProfile must reference a defined profile
  if (typeof raw.agent?.useProfile === "string") {
    if (!agentProfiles[raw.agent.useProfile]) {
      errors.push(`'agent.useProfile': profile "${raw.agent.useProfile}" is not defined in built-in profiles or agent.profiles`);
    }
  }

  if (raw.test) {
    if (typeof raw.test.command === "string") {
      validateTestCommand(raw.test.command, errors);
    }
    if (Array.isArray(raw.test.projectPaths)) {
      raw.test.projectPaths.forEach((entry, index) => validateProjectTestPath(entry, index, errors));
    }
    if (raw.test.timeout != null && !Number.isInteger(raw.test.timeout)) {
      errors.push("'test.timeout' must be a positive integer number of seconds");
    }
    if (raw.test.finalRegressionTimeout != null && !Number.isInteger(raw.test.finalRegressionTimeout)) {
      errors.push("'test.finalRegressionTimeout' must be a positive integer number of seconds");
    }
  }

  try {
    flowSpecRootFromConfig(raw);
  } catch (error) {
    errors.push(error.message);
  }

  if (raw.plugin) validatePluginConfig(raw.plugin, errors);
  if (errors.length > 0) {
    throw new Error(`Config validation failed:\n  - ${errors.join("\n  - ")}`);
  }

  return /** @type {import("./types.js").ProjectConfig} */ (raw);
}

const PLUGIN_ID_RE = /^[a-z0-9][a-z0-9._-]*$/;
const PLUGIN_COMMIT_RE = /^[0-9a-f]{40}$/;

function validatePluginConfig(plugin, errors) {
  if (Array.isArray(plugin.repos)) {
    errors.push("'plugin.repos': migrate to 'plugin.sources' and update packages[].repo to packages[].source");
  }
  const sourceIds = new Set();
  for (const [index, source] of (plugin.sources || []).entries()) {
    if (!PLUGIN_ID_RE.test(source.id)) errors.push(`'plugin.sources[${index}].id': invalid plugin source id`);
    if (sourceIds.has(source.id)) errors.push(`'plugin.sources[${index}].id': duplicate plugin source id "${source.id}"`);
    sourceIds.add(source.id);
    if (source.type === "local") {
      if (typeof source.path !== "string" || source.path.trim() === "") errors.push(`'plugin.sources[${index}].path': local source requires path`);
      if (typeof source.path === "string" && (path.isAbsolute(source.path) ? false : source.path.startsWith("../"))) errors.push(`'plugin.sources[${index}].path': unsafe local source path`);
    }
    if (source.type === "git" && typeof source.url !== "string" && typeof source.remote !== "string") errors.push(`'plugin.sources[${index}].remote': git source requires url or remote`);
    if (source.type === "npm") errors.push(`'plugin.sources[${index}]': npm sources are not supported yet`);
  }
  const packageIds = new Set();
  for (const [index, pkg] of (plugin.packages || []).entries()) {
    if (!PLUGIN_ID_RE.test(pkg.id)) errors.push(`'plugin.packages[${index}].id': invalid plugin package id`);
    if (packageIds.has(pkg.id)) errors.push(`'plugin.packages[${index}].id': duplicate plugin package id "${pkg.id}"`);
    packageIds.add(pkg.id);
    if (Object.prototype.hasOwnProperty.call(pkg, "repo")) errors.push(`'plugin.packages[${index}].repo': migrate to 'plugin.packages[${index}].source'`);
    if (!sourceIds.has(pkg.source)) errors.push(`'plugin.packages[${index}].source': unknown plugin source "${pkg.source}"`);
    if (!PLUGIN_COMMIT_RE.test(pkg.commit)) errors.push(`'plugin.packages[${index}].commit': must be a 40-character lowercase git commit`);
  }
}

const TEST_COMMAND_FORBIDDEN = /(\|\||&&|[|&;<>`$()]|\*|\?|\[|\]|\{|\})/;

function validateTestCommand(command, errors) {
  if (TEST_COMMAND_FORBIDDEN.test(command)) {
    errors.push("'test.command' contains unsupported shell control or expansion syntax");
  }
}

function validateProjectTestPath(entry, index, errors) {
  const prefix = `'test.projectPaths[${index}]'`;
  if (typeof entry !== "string" || entry.length === 0) {
    errors.push(`${prefix} must be a non-empty string`);
    return;
  }
  if (path.isAbsolute(entry)) errors.push(`${prefix} must be root-relative`);
  const hasParentTraversal = entry === ".." || entry.startsWith("../") || entry.endsWith("/..") || entry.includes("/../");
  if (entry.includes("\\") || hasParentTraversal) errors.push(`${prefix} must be a root-relative POSIX path without parent traversal`);
  if (/[*?[\\\]{};$|&<>`$()]/.test(entry)) errors.push(`${prefix} must not contain globs or shell metacharacters`);
}

// ---------------------------------------------------------------------------
// Spec-Driven Development 設定管理
// ---------------------------------------------------------------------------

/**
 * .sennel/config.json を読み込みバリデーションする。
 *
 * @param {string} root - リポジトリルート
 * @returns {import("./types.js").ProjectConfig}
 */
export function loadConfig(root, options = {}) {
  return loadConfigFromManagedDirectory(managedDir(root), options);
}

/**
 * Validate a config boundary at an explicitly supplied managed directory.
 * Migration uses this to inspect a staged legacy directory without teaching
 * normal runtime about legacy names.
 */
export function loadConfigFromManagedDirectory(directory, options = {}) {
  const raw = loadRawConfigFromManagedDirectory(directory);
  const pluginConfig = loadEnabledPluginConfig(directory, raw);
  const merged = mergeDefaults(raw, pluginConfig.defaults);
  return validate(merged, { ...options, schema: mergeConfigSchemas(CONFIG_SCHEMA, pluginConfig.schemas) });
}

export function loadRawConfig(root) {
  return loadRawConfigFromManagedDirectory(managedDir(root));
}

export function loadRawConfigFromManagedDirectory(directory) {
  const raw = loadJsonFile(path.join(directory, "config.json"));
  const localPath = path.join(directory, "config.local.json");
  if (!fs.existsSync(localPath)) return raw;
  const local = loadJsonFile(localPath);
  if (!local || typeof local !== "object" || Array.isArray(local)) {
    throw new Error("config.local.json must be a non-null object");
  }
  return mergeConfigOverlay(raw, local);
}

export function mergeConfigOverlay(base, overlay, segments = []) {
  if (Array.isArray(overlay)) {
    if (segments.join(".") === "plugin.sources" || segments.join(".") === "plugin.packages") {
      return mergeEntriesById(base, overlay);
    }
    return structuredClone(overlay);
  }
  if (!overlay || typeof overlay !== "object") return overlay;
  const out = base && typeof base === "object" && !Array.isArray(base) ? structuredClone(base) : {};
  for (const [key, value] of Object.entries(overlay)) {
    out[key] = mergeConfigOverlay(out[key], value, [...segments, key]);
  }
  return out;
}

function mergeEntriesById(base, overlay) {
  const out = Array.isArray(base) ? structuredClone(base) : [];
  const indexById = new Map(out.map((entry, index) => [entry?.id, index]).filter(([id]) => typeof id === "string"));
  for (const entry of overlay) {
    const next = structuredClone(entry);
    const index = indexById.get(next?.id);
    if (index == null) {
      indexById.set(next?.id, out.length);
      out.push(next);
    } else {
      out[index] = mergeConfigOverlay(out[index], next);
    }
  }
  return out;
}

function loadEnabledPluginConfig(managedDirectory, raw) {
  const schemas = [];
  const defaults = [];
  for (const pkg of raw?.plugin?.packages || []) {
    if (pkg.enabled === false) continue;
    const pluginRoot = path.join(managedDirectory, "plugins", pkg.id);
    const manifestPath = path.join(pluginRoot, "plugin.json");
    if (!fs.existsSync(manifestPath)) continue;
    try {
      const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
      const config = manifest.contributions?.config;
      if (config?.schema) schemas.push(loadJsonFile(path.join(pluginRoot, config.schema)));
      if (config?.defaults) defaults.push(migratePluginDefaultNamespaces(loadJsonFile(path.join(pluginRoot, config.defaults))));
    } catch (_) {
      continue;
    }
  }
  return { schemas, defaults };
}

function migratePluginDefaultNamespaces(raw) {
  return structuredClone(raw || {});
}

function mergeConfigSchemas(base, schemas) {
  if (!schemas.length) return base;
  const merged = {
    ...base,
    properties: { ...base.properties },
  };
  for (const schema of schemas) {
    for (const [key, value] of Object.entries(schema.properties || {})) {
      merged.properties[key] = mergeSchemaNode(merged.properties[key], value);
    }
  }
  return merged;
}

function mergeSchemaNode(base, extension) {
  if (!base || !extension || base.type !== "object" || extension.type !== "object") return extension || base;
  const merged = {
    ...base,
    ...extension,
    properties: { ...(base.properties || {}) },
  };
  for (const [key, value] of Object.entries(extension.properties || {})) {
    merged.properties[key] = mergeSchemaNode(merged.properties[key], value);
  }
  return merged;
}

function mergeDefaults(raw, defaults) {
  if (!defaults.length) return raw;
  let merged = structuredClone(raw);
  for (const defaultsObject of defaults) merged = mergeMissing(merged, defaultsObject);
  return merged;
}

function mergeMissing(target, defaults) {
  if (!defaults || typeof defaults !== "object" || Array.isArray(defaults)) return target;
  const out = { ...target };
  for (const [key, value] of Object.entries(defaults)) {
    if (out[key] == null) {
      out[key] = value;
    } else if (
      typeof out[key] === "object" && out[key] !== null && !Array.isArray(out[key])
      && typeof value === "object" && value !== null && !Array.isArray(value)
    ) {
      out[key] = mergeMissing(out[key], value);
    }
  }
  return out;
}

/**
 * src/lib/container.js
 *
 * Dependency container for CLI-wide initialized services (config, logger, paths,
 * agent, i18n, flowManager, etc.). Built once in src/sennel.js and
 * referenced by all dispatchers and commands via the module-level `container`
 * export.
 */

import path from "path";
import { repoRoot, sourceRoot, isInsideWorktree, getMainRepoPath } from "./cli.js";
import { loadConfig, loadJsonFile, managedConfigPath, managedDir, managedOutputDir, resolveWorkDir } from "./config.js";
import { Logger } from "./log.js";
import { Agent } from "./agent.js";
import { ProviderRegistry } from "./provider.js";
import { translate } from "./i18n.js";
import { FlowManager } from "./flow-manager.js";
import { FINALIZE_CLEANUP_DURABLE_AGENT_WORK_DIR } from "./finalize-cleanup-paths.js";
import { DataSource } from "../docs/lib/data-source.js";
import { Scannable } from "../docs/lib/scan-source.js";
import {
  Renderable,
  Table,
  BulletList,
  OrderedList,
  Paragraph,
  CodeBlock,
  Blockquote,
  Heading,
  Fragment,
} from "../docs/lib/renderable.js";
import { AnalysisEntry, ANALYSIS_META_KEYS, iterateAnalysisCategories } from "../docs/lib/analysis-entry.js";
import { findFiles, collectFiles, patternToRegex, parseFile, parsePHPFile, parseJSFile, camelToSnake, pluralize, getFileStats } from "../docs/lib/scanner.js";
import { stripBlockComments, extractArrayBody, extractTopLevelKeys, extractQuotedStrings } from "../docs/lib/php-array-parser.js";
import { getLangHandler } from "../docs/lib/lang-factory.js";
import { hasPathPrefix, hasSegmentPath, hasAnyPathPrefix } from "./path-match.js";
import { parseTOML } from "../docs/lib/toml-parser.js";
import { flowSpecRootFromConfig } from "./flow-workspace.js";

export class Container {
  constructor() {
    this._map = new Map();
    this._presets = new Map();
  }

  register(name, value) {
    this._map.set(name, value);
  }

  set(name, value) {
    this._map.set(name, value);
  }

  get(name) {
    if (!this._map.has(name)) {
      throw new Error(`Container: dependency not registered: ${name}`);
    }
    return this._map.get(name);
  }

  has(name) {
    return this._map.has(name);
  }

  /**
   * Register a preset's public surface (DataSource classes, etc.).
   * Called by the preset loader after invoking the preset's register(container)
   * factory. Enables child presets to extend parent preset classes via
   * container.getPreset(parent).dataSources[name].
   *
   * @param {string} key - preset key (e.g. "sample-preset", "child-preset")
   * @param {{ dataSources: Object<string, Function> }} registration
   */
  registerPreset(key, registration) {
    this._presets.set(key, registration);
  }

  getPreset(key) {
    return this._presets.get(key) ?? null;
  }

  hasPreset(key) {
    return this._presets.has(key);
  }

  reset() {
    this._map.clear();
    this._presets.clear();
  }
}

export const container = new Container();

/**
 * Build path service object. All fields are absolute paths.
 *
 * Work-directory priority: opts.agentWorkDirOverride > config.agent.workDir > .tmp.
 * `logDir` is computed once here and reused by Logger.
 */
function buildPaths(root, config, opts = {}) {
  const durableRoot = opts.durableRoot ? path.resolve(opts.durableRoot) : null;
  const agentWorkDir = durableRoot
    ? path.join(durableRoot, FINALIZE_CLEANUP_DURABLE_AGENT_WORK_DIR)
    : resolveWorkDir(root, config, opts);
  const logDir = config?.logs?.dir
    ? path.resolve(durableRoot || root, config.logs.dir)
    : path.join(agentWorkDir, "logs");
  return Object.freeze({
    root,
    srcRoot: sourceRoot(),
    managedDir: managedDir(root),
    outputDir: managedOutputDir(root),
    agentWorkDir,
    logDir,
    configPath: managedConfigPath(root),
  });
}

/**
 * Initialize the module-level container. Called once from src/sennel.js.
 * Subsequent dispatchers and commands import `container` directly.
 *
 * Best-effort initialization: if config is absent (setup not run yet, help-only
 * invocation, etc.), `null` is registered for config so that commands which
 * require config can be rejected at the dispatch layer via `requiresConfig`,
 * while commands that do not require config (help, setup, etc.) can still
 * start. Logger init is skipped when config is absent.
 *
 * @param {Object} [opts]
 * @param {string} [opts.entryCommand] - Full argv string for Logger metadata
 * @param {string} [opts.agentWorkDirOverride] - Per-invocation agent work dir
 * @param {boolean} [opts.finalizeCleanupDurablePaths] - Keep cleanup logs under
 *   repository authority after the managed worktree is removed.
 * @param {boolean} [opts.allowInvalidConfig] - Initialize with null config so
 *   migration commands can repair config that strict validation rejects.
 * @param {"ambient"|"none"} [opts.flowAttribution] - Ambient Flow attribution
 *   policy for command-level diagnostic logging.
 */
export function initContainer(opts = {}) {
  // Idempotent: if already initialized (e.g. by sennel.js before a
  // dispatcher was imported), do not re-run initialization. This lets
  // each dispatcher safely call initContainer() at its top to support
  // standalone execution (direct `node src/flow.js` invocation in tests)
  // without violating R1's one-time-initialization invariant.
  if (container.has("config")) return;

  const root = repoRoot();
  let config = null;
  let configLoaded = false;
  try {
    config = loadConfig(root, { allowMissingType: true });
    configLoaded = true;
  } catch (err) {
    if (err?.code !== "ERR_MISSING_FILE") {
      if (opts.allowInvalidConfig === true) {
        config = null;
        configLoaded = false;
      } else {
      process.stderr.write(`[sennel] config load failed: ${err?.message}\n`);
      throw err;
      }
    }
  }

  const inWorktree = isInsideWorktree(root);
  const mainRoot = inWorktree ? getMainRepoPath(root) : root;
  let mainConfig = config;
  if (inWorktree) {
    try {
      mainConfig = loadConfig(mainRoot, { allowMissingType: true });
    } catch (err) {
      // A linked worktree can be a standalone project fixture. Its common
      // repository is not required to carry Sennel configuration; use the
      // worktree configuration unless a readable main configuration exists.
      if (err?.code !== "ERR_MISSING_FILE") throw err;
    }
  }
  const flowSpecRoot = flowSpecRootFromConfig(mainConfig);
  const durableFinalizeRoot = opts.finalizeCleanupDurablePaths === true && inWorktree
    ? mainRoot
    : null;
  const paths = buildPaths(root, config, {
    agentWorkDirOverride: opts.agentWorkDirOverride,
    durableRoot: durableFinalizeRoot,
  });

  container.register("root", root);
  container.register("config", config);
  container.register("paths", paths);
  container.register("inWorktree", inWorktree);
  container.register("mainRoot", mainRoot);
  container.register("flowSpecRoot", flowSpecRoot);
  const flowManager = new FlowManager({ root, mainRoot, inWorktree, specRoot: flowSpecRoot });
  container.register("flowManager", flowManager);
  const loggerFlowManager = durableFinalizeRoot
    ? flowManager.forRoot(durableFinalizeRoot)
    : flowManager;
  const logger = new Logger({
    logDir: paths.logDir,
    enabled: configLoaded && config?.logs?.enabled === true,
    entryCommand: opts.entryCommand ?? null,
    flowManager: loggerFlowManager,
    flowAttribution: opts.flowAttribution ?? "ambient",
    cwd: durableFinalizeRoot || root,
  });
  container.register("logger", logger);
  if (configLoaded) {
    logger.event("config-loaded", { path: paths.configPath, keys: Object.keys(config) });
  }

  const registry = new ProviderRegistry(config?.agent?.providers || {});
  const agent = new Agent({ config, paths, registry, logger, flowManager });
  container.register("agent", agent);
  globalThis.__sennelPluginAgent = agent;
  container.register("i18n", translate());
  container.register("lang", config?.lang);

  // Base classes and utilities exposed to presets. Presets access these via
  // container.get("base.DataSource") etc. so they never need to import from
  // sennel internal paths directly.
  container.register("base.DataSource", DataSource);
  container.register("base.Scannable", Scannable);
  container.register("base.AnalysisEntry", AnalysisEntry);
  container.register("base.ANALYSIS_META_KEYS", ANALYSIS_META_KEYS);
  container.register("base.iterateAnalysisCategories", iterateAnalysisCategories);
  container.register("base.Renderable", Renderable);
  container.register("base.Table", Table);
  container.register("base.BulletList", BulletList);
  container.register("base.OrderedList", OrderedList);
  container.register("base.Paragraph", Paragraph);
  container.register("base.CodeBlock", CodeBlock);
  container.register("base.Blockquote", Blockquote);
  container.register("base.Heading", Heading);
  container.register("base.Fragment", Fragment);
  container.register("scanner.findFiles", findFiles);
  container.register("scanner.collectFiles", collectFiles);
  container.register("scanner.patternToRegex", patternToRegex);
  container.register("scanner.parseFile", parseFile);
  container.register("scanner.parsePHPFile", parsePHPFile);
  container.register("scanner.parseJSFile", parseJSFile);
  container.register("scanner.camelToSnake", camelToSnake);
  container.register("scanner.pluralize", pluralize);
  container.register("scanner.getFileStats", getFileStats);
  container.register("phpParser.stripBlockComments", stripBlockComments);
  container.register("phpParser.extractArrayBody", extractArrayBody);
  container.register("phpParser.extractTopLevelKeys", extractTopLevelKeys);
  container.register("phpParser.extractQuotedStrings", extractQuotedStrings);
  container.register("lang.getHandler", getLangHandler);
  container.register("pathMatch.hasPathPrefix", hasPathPrefix);
  container.register("pathMatch.hasSegmentPath", hasSegmentPath);
  container.register("pathMatch.hasAnyPathPrefix", hasAnyPathPrefix);
  container.register("toml.parse", parseTOML);
  container.register("config.loadJsonFile", loadJsonFile);
}

/**
 * src/lib/dispatcher.js
 *
 * Unified command dispatcher for all domains (flow / docs / check / metrics).
 * Replaces the per-domain ad-hoc runners with one path:
 *
 *   parseArgs(argv, entry.args)         — consistent CLI parsing
 *   → entry.pre?(ctx)                   — lifecycle pre
 *   → cmd.run(container, input)         — Command contract
 *   → entry.post?(ctx, result)          — lifecycle post (success only)
 *   → entry.onError?(ctx, err)          — lifecycle onError (failure only)
 *   → write envelope JSON | raw stdout  — per Command.outputMode
 *
 * Writes to stdout and setExitCode can be injected for testing.
 */

import { parseArgs as cliParseArgs } from "./cli.js";
import { Command } from "./command.js";
import { Envelope } from "./flow-envelope.js";
import { RuntimeLogBlockWriter } from "./runtime-log.js";
import { FlowTargetBinding, targetMismatchEnvelopeForInput } from "./flow-target-guard.js";
import { findActiveNode, taskIdForResolvedStep } from "../flow/definition.js";
import {
  AwaitingDecisionOutcome,
  ExternalBlockedOutcome,
  StepAttempt,
} from "../flow/lib/step-outcome.js";
import {
  attachFlowContinuation,
  attachUserActionPrompt,
  FlowContinuation,
} from "../flow/lib/user-action-prompt.js";
import { guardedCommand } from "../flow/lib/guarded-command.js";
import { FinalizeFlowStateOwner } from "../flow/lib/finalize-flow-state-owner.js";
import { FatalPostHookError } from "./post-hook-error.js";
import { AgentFailure } from "./agent-failure.js";
import { DefinitionLifecycleAttemptBinding } from "../flow/lib/definition-lifecycle-failure.js";

function attachNonblockingContinuation(envelope, ctx, reason) {
  const state = ctx?.flowState;
  if (!(envelope instanceof Envelope) || state?.policy?.nonblocking?.enabled !== true) return envelope;
  if (envelope.data?.actionPrompt || envelope.data?.continuation) return envelope;
  const binding = FlowTargetBinding.captureContext(ctx);
  return attachFlowContinuation(envelope, new FlowContinuation({
    actionId: "REFRESH_NONBLOCKING_FLOW",
    nextAction: guardedCommand("sennel flow get next-action", state, binding),
    instruction: "Refresh the guarded next action and continue the normal Flow route.",
    reason,
  }));
}

function throwUnexpected(extras) {
  const unknownOpt = extras.find((v) => typeof v === "string" && v.startsWith("-"));
  if (unknownOpt) throw new Error(`Unknown option: ${unknownOpt}`);
  throw new Error(`Unexpected argument: ${extras[0]}`);
}

function splitArgsBySpec(argv, flagSet, optionSet, optionalOptionSet) {
  const nonPositional = [];
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "-h" || a === "--help") {
      nonPositional.push(a);
      continue;
    }
    if (flagSet.has(a)) {
      nonPositional.push(a);
      continue;
    }
    if (optionSet.has(a)) {
      if (i + 1 >= argv.length || String(argv[i + 1]).trim() === "" || String(argv[i + 1]).startsWith("-")) {
        throw new Error(`Missing value for option: ${a}`);
      }
      nonPositional.push(a);
      nonPositional.push(argv[++i]);
      continue;
    }
    const equalsOption = [...optionSet].find((option) => a.startsWith(`${option}=`));
    if (equalsOption) {
      const value = a.slice(equalsOption.length + 1);
      if (!value) throw new Error(`Missing value for option: ${equalsOption}`);
      nonPositional.push(equalsOption, value);
      continue;
    }
    if (optionalOptionSet.has(a)) {
      nonPositional.push(a);
      const value = argv[i + 1];
      if (value != null && String(value).trim() !== "" && !String(value).startsWith("-")) {
        nonPositional.push(argv[++i]);
      }
      continue;
    }
    // Unrecognized `-`-prefixed token → unknown option; non-dash tokens fall
    // through as positional values.
    if (typeof a === "string" && a.startsWith("-")) {
      throw new Error(`Unknown option: ${a}`);
    }
    positional.push(a);
  }
  return { nonPositional, positional };
}

/**
 * Parse argv into an input object according to entry.args.
 *   - flags / options use camelCase conversion via cli.parseArgs.
 *   - positional values are assigned by name: ctx[positional[i]] = values[i].
 *
 * When `entry.args` is absent (typical for legacy adapter entries that parse
 * their own argv internally), return an empty input so the raw args reach
 * the command unaltered via `_rawArgs` (set later in dispatch()).
 */
export function parseEntryInput(entry, argv) {
  if (!entry.args) {
    if (entry.passthroughArgs) {
      return { help: argv.includes("-h") || argv.includes("--help") };
    }
    // Strict no-arg entry: reject any extras besides help.
    const extras = argv.filter((a) => a !== "-h" && a !== "--help");
    if (extras.length > 0) throwUnexpected(extras);
    return { help: argv.includes("-h") || argv.includes("--help") };
  }
  const spec = entry.args || {};
  const positionalNames = spec.positional || [];
  const flags = spec.flags || [];
  const options = spec.options || [];
  const optionalOptions = spec.optionalOptions || [];

  const { nonPositional, positional } = splitArgsBySpec(
    argv,
    new Set(flags),
    new Set(options),
    new Set(optionalOptions),
  );

  const parsed = cliParseArgs(nonPositional, { flags, options, optionalOptions });

  for (let i = 0; i < positionalNames.length && i < positional.length; i++) {
    parsed[positionalNames[i]] = positional[i];
  }
  if (spec.rest) {
    parsed[spec.rest] = positional.slice(positionalNames.length);
  } else if (positional.length > positionalNames.length) {
    throwUnexpected(positional.slice(positionalNames.length));
  }
  return parsed;
}

const FINALIZE_CLEANUP_REPORT_HEADER = "Finalize Report";
const FINALIZE_CLEANUP_REPORT_MISSING_CODE = "REPORT_MISSING";
const FINALIZE_CLEANUP_WARNING_MESSAGE_LIMIT = 3;
const FINALIZE_CLEANUP_WARNING_TEXT_LIMIT = 600;

function runtimeLogRunId(hookCtx) {
  return hookCtx?.flowState?.runId || hookCtx?.runId || "no-flow";
}

function runtimeLogFlowId(hookCtx) {
  return hookCtx?.specId || "no-flow";
}

function runtimeLogAllowed(entry, hookCtx) {
  return !(
    entry.runtimeLog?.writeWhenNoFlow === false
    && hookCtx?.flowState == null
  );
}

function runtimeLogRoot({ entry, hookCtx, container }) {
  const fallbackRoot = hookCtx.root || container.get("paths").root;
  if (entry.runtimeLog?.authority !== "main-repository") return fallbackRoot;
  if (!hookCtx?.flowManager || !hookCtx?.flowState?.worktree) return fallbackRoot;
  const { mainRepoPath } = hookCtx.flowManager.resolveWorktreePaths(hookCtx.flowState);
  return mainRepoPath || fallbackRoot;
}

function attachRuntimeLog(envelope, metadata) {
  if (!(envelope instanceof Envelope) || !metadata) return envelope;
  const runtimeLog = {
    runId: metadata.runId,
    sequence: metadata.sequence,
  };
  envelope.data = envelope.data && typeof envelope.data === "object" && !Array.isArray(envelope.data)
    ? { ...envelope.data, runtimeLog }
    : { runtimeLog };
  return envelope;
}

function runtimeLogStepId(entry, hookCtx, result) {
  const spec = entry.runtimeLog;
  if (!spec || spec.stepMetadata === false) return null;
  if (typeof spec.stepId === "function") return spec.stepId(hookCtx, result);
  if (typeof spec.stepId === "string") return spec.stepId;
  return null;
}

async function persistFinalizeCleanupPostReturnMetadata({
  envelopeKey,
  hookCtx,
  metadata,
  commandModule,
  commitCompletion = false,
}) {
  if (envelopeKey !== "finalize-cleanup" || !hookCtx?.flowManager || !hookCtx?.specId) return;
  const state = hookCtx.flowState || hookCtx.flowManager.loadReadOnly(hookCtx.specId);
  let retainedMetadata = null;
  if (metadata && state) {
    const { mainRepoPath } = hookCtx.flowManager.resolveWorktreePaths(state);
    const repositoryRoot = mainRepoPath || hookCtx.flowManager.specLocation(hookCtx.specId).repositoryRoot;
    const recordFinalizeCleanupPostCommandMetadata = commandModule?.recordFinalizeCleanupPostCommandMetadata;
    if (typeof recordFinalizeCleanupPostCommandMetadata !== "function") {
      throw new Error("finalize-cleanup command module has no post-command metadata recorder");
    }
    const stateOwner = FinalizeFlowStateOwner.forMainContext({
      ...hookCtx,
      mainRoot: repositoryRoot,
    });
    retainedMetadata = recordFinalizeCleanupPostCommandMetadata({
      flowManager: stateOwner.flowManager,
      specId: hookCtx.specId,
      runtimeLog: metadata.toStepMetadata(),
    });
  }
  if (!commitCompletion) return;
  const commitFinalizeCleanupPostCommandMetadata = commandModule?.commitFinalizeCleanupPostCommandMetadata;
  if (typeof commitFinalizeCleanupPostCommandMetadata !== "function") {
    throw new Error("finalize-cleanup command module has no post-command completion committer");
  }
  commitFinalizeCleanupPostCommandMetadata({
    flowManager: hookCtx.flowManager,
    specId: hookCtx.specId,
    writtenPaths: retainedMetadata?.writtenPaths || [],
  });
}

function findWarning(envelope, code) {
  return (envelope.errors || []).find((entry) => entry?.level === "warn" && entry?.code === code) || null;
}

function truncateText(text, limit) {
  if (text.length <= limit) return text;
  return `${text.slice(0, limit)}...`;
}

function formatWarningMessages(warning) {
  const messages = Array.isArray(warning?.messages) ? warning.messages : [];
  const shown = messages.slice(0, FINALIZE_CLEANUP_WARNING_MESSAGE_LIMIT);
  const suffix = messages.length > shown.length
    ? ` ... (${messages.length - shown.length} more message(s))`
    : "";
  return truncateText(`${shown.join(" ")}${suffix}`, FINALIZE_CLEANUP_WARNING_TEXT_LIMIT);
}

function formatFinalizeCleanupReportDisplay({ envelopeKey, envelope }) {
  if (envelopeKey !== "finalize-cleanup" || !(envelope instanceof Envelope) || envelope.ok !== true) return null;
  const report = envelope.data?.report;
  if (report && typeof report.text === "string") return `${FINALIZE_CLEANUP_REPORT_HEADER}\n${report.text}`;
  if (report !== null) return null;

  const warning = findWarning(envelope, FINALIZE_CLEANUP_REPORT_MISSING_CODE);
  if (!warning) return null;
  return `${FINALIZE_CLEANUP_REPORT_MISSING_CODE}: ${formatWarningMessages(warning)}\n`;
}

function emitFinalizeCleanupReportDisplay({ envelopeKey, envelope, writeErr }) {
  const text = formatFinalizeCleanupReportDisplay({ envelopeKey, envelope });
  if (text) writeErr(text);
}

function settleTypedStepOutcome(envelope, result) {
  if (!(envelope instanceof Envelope) || !result?.stepAttempt) return;
  const attempt = StepAttempt.fromStored(result.stepAttempt);
  if (!(attempt.outcome instanceof ExternalBlockedOutcome)
    && !(attempt.outcome instanceof AwaitingDecisionOutcome)) return;
  if (
    attempt.outcome instanceof ExternalBlockedOutcome
    && ["execute_command", "execute_step", "repair_evidence"].includes(result.directive?.kind)
    && result.directive?.terminal === false
    && result.directive?.requiresUserAction === false
  ) {
    // The typed attempt records why the prior action stopped. A newer
    // deterministic directive is the durable recovery route and must remain a
    // successful guarded next-action response.
    return;
  }
  envelope.ok = false;
  envelope.errors.push({
    level: "fatal",
    code: attempt.outcome instanceof AwaitingDecisionOutcome
      ? "STEP_DECISION_REQUIRED"
      : "STEP_EXTERNAL_BLOCKED",
    messages: [attempt.outcome.resumeInstruction],
  });
  if (attempt.outcome instanceof AwaitingDecisionOutcome) {
    attachUserActionPrompt(envelope, attempt.outcome.prompt);
  }
}

function recordDefinitionLifecycleToolingFailure(binding, error, fallbackCode, writeErr, commandResult = null) {
  if (!(binding instanceof DefinitionLifecycleAttemptBinding)) return false;
  try {
    return binding.toolingFailure(error, fallbackCode, commandResult);
  } catch (recordingError) {
    writeErr(`[definition lifecycle failure] ${recordingError.message || recordingError}\n`);
    return false;
  }
}

/**
 * Dispatch a single entry.
 *
 * @param {Object}   args
 * @param {import("./container.js").Container} args.container
 * @param {Object}   args.entry        registry entry
 * @param {string[]} args.argv         command-specific argv tail
 * @param {string}   [args.envelopeType]
 * @param {string}   [args.envelopeKey]
 * @param {(s: string) => void} [args.stdout]        override for tests
 * @param {(code: number) => void} [args.setExitCode] override for tests
 * @param {(s: string) => void} [args.stderr]        override for tests
 * @param {boolean} [args.runtimeLog]  enable flow-run human-readable runtime log
 */
export async function dispatch({
  container,
  entry,
  argv,
  envelopeType,
  envelopeKey,
  runtimeLog: enableRuntimeLog = false,
  stdout,
  stderr,
  setExitCode,
  buildHookCtx,
}) {
  const baseWriteOut = stdout || ((s) => process.stdout.write(s));
  let runtimeLog = null;
  const baseWriteErr = stderr || ((s) => process.stderr.write(s));
  const processCaptureSuppressed = { stdout: 0, stderr: 0 };
  const withProcessCaptureSuppressed = (stream, fn) => {
    processCaptureSuppressed[stream] += 1;
    try {
      return fn();
    } finally {
      processCaptureSuppressed[stream] -= 1;
    }
  };
  const writeOut = (s) => {
    if (runtimeLog) runtimeLog.capture("stdout", s);
    return withProcessCaptureSuppressed("stdout", () => baseWriteOut(s));
  };
  const writeErr = (s) => {
    if (runtimeLog) runtimeLog.capture("stderr", s);
    return withProcessCaptureSuppressed("stderr", () => baseWriteErr(s));
  };
  let recordedExitCode = 0;
  const baseSetExit = setExitCode || ((code) => { process.exitCode = code; });
  const setExit = (code) => {
    recordedExitCode = code;
    baseSetExit(code);
  };
  let closedRuntimeLogMetadata = null;
  let restoreStreams = null;
  const buildRuntimeHookCtx = (parsedInput) => {
    const skipAmbientFlowContext = entry.skipAmbientFlowContext === true;
    if (skipAmbientFlowContext || !buildHookCtx) return { container, ...parsedInput };
    return { ...buildHookCtx(container, parsedInput), ...parsedInput };
  };
  const openRuntimeLog = (hookCtx) => {
    if (
      runtimeLog
      || enableRuntimeLog !== true
      || !container.has("paths")
      || !runtimeLogAllowed(entry, hookCtx)
    ) return;
    runtimeLog = RuntimeLogBlockWriter.forDispatch({
      root: runtimeLogRoot({ entry, hookCtx, container }),
      flowId: runtimeLogFlowId(hookCtx),
      runId: runtimeLogRunId(hookCtx),
      envelopeType,
      envelopeKey,
    });
    const originalStdoutWrite = process.stdout.write;
    const originalStderrWrite = process.stderr.write;
    process.stdout.write = function(chunk, encoding, cb) {
      if (runtimeLog && processCaptureSuppressed.stdout === 0) runtimeLog.capture("stdout", chunk);
      return originalStdoutWrite.call(this, chunk, encoding, cb);
    };
    process.stderr.write = function(chunk, encoding, cb) {
      if (runtimeLog && processCaptureSuppressed.stderr === 0) runtimeLog.capture("stderr", chunk);
      return originalStderrWrite.call(this, chunk, encoding, cb);
    };
    restoreStreams = () => {
      process.stdout.write = originalStdoutWrite;
      process.stderr.write = originalStderrWrite;
    };
  };
  const closeRuntimeLog = () => {
    if (!runtimeLog || closedRuntimeLogMetadata) return closedRuntimeLogMetadata;
    closedRuntimeLogMetadata = runtimeLog.close(recordedExitCode);
    return closedRuntimeLogMetadata;
  };

  // 1. Parse argv → input. _rawArgs preserved for legacy adapters that
  //    need to reconstruct process.argv before calling into old main().
  let input;
  try {
    input = parseEntryInput(entry, argv);
    input._rawArgs = argv;
  } catch (err) {
    const parseHookCtx = buildRuntimeHookCtx({});
    openRuntimeLog(parseHookCtx);
    const mode = await resolveOutputMode(entry);
    const helpHint = entry.helpPath
      ? `Run: ${entry.helpPath}`
      : `Run: sennel ${envelopeType || "flow"} ${envelopeKey || ""} --help`.trimEnd();
    if (mode === "envelope" || entry.parseErrorsAsEnvelope === true) {
      const env = Envelope.fail(envelopeType || "run", envelopeKey || "?", "ARGS_ERROR", [
        String(err.message || err),
        helpHint,
      ]);
      attachRuntimeLog(env, runtimeLog?.metadata);
      writeOut(JSON.stringify(env.toJSON(), null, 2) + "\n");
    } else {
      writeErr(`${err.message || err}\n${helpHint}\n`);
      if (runtimeLog?.metadata) {
        writeErr(`runtimeLog.runId=${runtimeLog.metadata.runId} runtimeLog.sequence=${runtimeLog.metadata.sequence}\n`);
      }
    }
    setExit(1);
    closeRuntimeLog();
    if (restoreStreams) restoreStreams();
    return;
  }

  // 2. help shortcut
  if (input.help && entry.help) {
    writeOut(`${entry.help}\n`);
    return;
  }

  // 3. Resolve and guard the flow target before loading or validating the
  // command module. A mismatch cannot reach command-owned validation,
  // lifecycle hooks, execution, or step metadata persistence.
  const hookCtx = buildRuntimeHookCtx(input);
  const emitTargetFailure = (failure) => {
    attachRuntimeLog(failure, enableRuntimeLog === true && container.has("paths")
      ? { runId: runtimeLogRunId(hookCtx) }
      : null);
    writeOut(JSON.stringify(failure.toJSON(), null, 2) + "\n");
    setExit(1);
  };
  const recognizedTargetResolutionError = [
    "ACTIVE_FLOW_MISMATCH",
    "FLOW_TARGET_NOT_FOUND",
    "FLOW_TARGET_AMBIGUOUS",
    "FLOW_TARGET_RECOVERY_REQUIRED",
    "FLOW_TARGET_AUTHORITY_CORRUPT",
  ].includes(hookCtx.flowResolutionError?.code)
    || hookCtx.flowResolutionError?.code?.startsWith("FLOW_TARGET_AUTHORITY_");
  const targetResolutionError = hookCtx.flowResolutionError && (
    entry.explicitTargetResolution === true || recognizedTargetResolutionError
  )
    ? hookCtx.flowResolutionError
    : null;
  if (
    targetResolutionError
    && !(
      entry.deferTargetNotFound === true
      && targetResolutionError.code === "FLOW_TARGET_NOT_FOUND"
    )
  ) {
    const failureCode = targetResolutionError.code === "FLOW_TARGET_NOT_FOUND"
      && entry.targetNotFoundAsMismatch === true
      ? "ACTIVE_FLOW_MISMATCH"
      : targetResolutionError.code || "FLOW_TARGET_RESOLUTION_FAILED";
    emitTargetFailure(Envelope.fail(
      envelopeType || "run",
      envelopeKey || "?",
      failureCode,
      targetResolutionError.message,
      targetResolutionError.data,
    ));
    return;
  }
  const targetMismatch = entry.targetGuard === false
    ? null
    : buildHookCtx
      ? targetMismatchEnvelopeForInput({
          type: envelopeType || "run",
          key: envelopeKey || "?",
          input,
          flowState: hookCtx.preparingFlowState ?? hookCtx.flowState,
          mainRoot: hookCtx.mainRoot || hookCtx.root,
          authorityRoot: hookCtx.root,
          worktreePath: hookCtx.flowState?.worktree === true ? hookCtx.root : undefined,
          context: hookCtx,
        })
      : null;
  if (targetMismatch) {
    emitTargetFailure(targetMismatch);
    return;
  }

  // 4. Load Command class
  const mod = await entry.command();
  const CommandClass = mod.default;
  if (!CommandClass || typeof CommandClass !== "function") {
    writeErr(`dispatcher: module has no default export (Command class)\n`);
    setExit(1);
    return;
  }
  Command.validate(CommandClass);

  const mode = CommandClass.outputMode;

  const runtimeLogActiveNode = hookCtx.flowState ? findActiveNode(hookCtx.flowState) : null;

  openRuntimeLog(hookCtx);

  const emitPreconditionFailure = (code, message) => {
    const env = Envelope.fail(envelopeType || "run", envelopeKey || "?", code, message);
    attachRuntimeLog(env, runtimeLog?.metadata);
    writeOut(JSON.stringify(env.toJSON(), null, 2) + "\n");
    setExit(1);
  };
  const persistRuntimeLogMetadata = (result) => {
    const metadata = closedRuntimeLogMetadata;
    const requestedStepId = runtimeLogStepId(entry, hookCtx, result);
    // Public task aliases name the current task leaf before it is confirmed.
    // Persist metadata under that immutable node id so a successful command
    // does not need a now-cleared current Attempt to resolve the alias again.
    const stepId = runtimeLogActiveNode?.scope === "task"
      && typeof requestedStepId === "string"
      && requestedStepId.startsWith("task-")
      ? runtimeLogActiveNode.stepId
      : requestedStepId;
    if (metadata && stepId && hookCtx.flowManager && hookCtx.flowState) {
      hookCtx.flowManager.setStepRuntimeLog(stepId, metadata.toStepMetadata(), {
        ...(hookCtx.specId ? { specId: hookCtx.specId } : {}),
        taskId: taskIdForResolvedStep(runtimeLogActiveNode, stepId),
      });
    }
  };

  // 5a. requiresConfig — reject early when the command declares config as a
  // precondition but the container has no config registered (setup not run).
  if (entry.requiresConfig && container.get("config") == null) {
    emitPreconditionFailure("NO_CONFIG", "config.json not found. Run sennel setup first.");
    closeRuntimeLog();
    persistRuntimeLogMetadata(null);
    if (restoreStreams) restoreStreams();
    return;
  }

  // 5b. requiresFlow (flow domain only — hooks expect flowState present).
  // Skipped for non-flow entries or when buildHookCtx is absent.
  if (entry.requiresFlow !== false && buildHookCtx && !hookCtx.flowState) {
    emitPreconditionFailure("NO_FLOW", "no active flow (flow.json not found)");
    closeRuntimeLog();
    persistRuntimeLogMetadata(null);
    if (restoreStreams) restoreStreams();
    return;
  }

  // Bind the exact active Attempt before any registry lifecycle hook can
  // confirm, fail, or replace it.  Error handling below can therefore record
  // a tooling failure only for this command's original Attempt.
  const lifecycleAttemptBinding = DefinitionLifecycleAttemptBinding.capture({
    hookCtx,
    envelopeType,
    envelopeKey,
    registryFailureOwnership: entry.failureOwnership ?? null,
  });

  // 6. pre
  if (entry.pre) {
    try {
      await entry.pre(hookCtx);
    } catch (err) {
      if (hookCtx.flowOutboxEntry && entry.onError) {
        try { await entry.onError(hookCtx, err); } catch (onErrorErr) {
          writeErr(`[onError hook] ${onErrorErr.message || onErrorErr}\n`);
        }
      }
      recordDefinitionLifecycleToolingFailure(
        lifecycleAttemptBinding,
        err,
        "PRE_HOOK_FAILED",
        writeErr,
      );
      await emitFailure({
        err,
        mode,
        envelopeType,
        envelopeKey,
        writeOut,
        writeErr,
        setExit,
        runtimeLogMetadata: runtimeLog?.metadata,
        flowContext: hookCtx,
      });
      closeRuntimeLog();
      persistRuntimeLogMetadata(null);
      if (restoreStreams) restoreStreams();
      return;
    }
  }

  // 7. execute via Command.run
  let result;
  let caught;
  if (hookCtx.flowOutboxEntry?.status === "done") {
    result = structuredClone(hookCtx.flowOutboxEntry.result);
    hookCtx.flowOutboxResumed = true;
  } else {
    try {
      const cmd = new CommandClass();
      input._envelopeType = envelopeType;
      input._envelopeKey = envelopeKey;
      const commandInput = hookCtx.flowOutboxEntry
        ? { ...input, flowOutboxEntry: hookCtx.flowOutboxEntry }
        : input;
      if (
        envelopeKey === "finalize-cleanup"
        && typeof mod.commitFinalizeCleanupPostCommandMetadata === "function"
      ) {
        commandInput._deferFinalizeCompletionCommit = true;
      }
      result = await cmd.run(container, commandInput);
    } catch (err) {
      caught = err;
    }
  }

  // 8a. Success path
  if (!caught) {
    // Keep the command result available to lifecycle settlement and runtime
    // metadata even when a post hook replaces only the public Envelope.
    let envelope;
    if (mode === "envelope") {
      // Commands may return an Envelope directly (e.g. Envelope.fail for
      // recoverable / user-avoidable outcomes). In that case honor it verbatim
      // rather than re-wrapping it in Envelope.ok.
      if (result instanceof Envelope) {
        envelope = result;
      } else {
        envelope = Envelope.ok(envelopeType || "run", envelopeKey || "?", result || {});
      }
    }
    let postFailed = false;
    // Skip post hooks when the command explicitly returned an ok:false envelope —
    // post hooks advance step status / counters assuming success, which would
    // fire incorrectly on a judgment-result rejection.
    const skipPost = result instanceof Envelope && result.ok === false;
    const deferFinalizeCompletion = !skipPost
      && envelopeKey === "finalize-cleanup"
      && typeof mod.commitFinalizeCleanupPostCommandMetadata === "function";
    if (skipPost) {
      const failure = new Error(
        result.errors.flatMap((item) => item.messages || []).join("; ") || `${envelopeKey || "command"} failed`,
      );
      failure.code = result.errors.find((item) => item?.level === "fatal")?.code
        || result.errors[0]?.code
        || "COMMAND_ENVELOPE_FAILED";
      failure.data = result.data;
      if (hookCtx.flowOutboxEntry && entry.onError) {
        try {
          await entry.onError(hookCtx, failure);
        } catch (onErrorErr) {
          postFailed = true;
          if (mode === "envelope") envelope.addWarning("ON_ERROR_HOOK_FAILED", onErrorErr.message || String(onErrorErr));
          else writeErr(`[onError hook] ${onErrorErr.message || onErrorErr}\n`);
        }
      }
      recordDefinitionLifecycleToolingFailure(
        lifecycleAttemptBinding,
        failure,
        "COMMAND_ENVELOPE_FAILED",
        writeErr,
      );
    }
    if (entry.post && !skipPost) {
      try {
        const postResult = await entry.post(hookCtx, result);
        if (postResult instanceof Envelope && mode === "envelope") envelope = postResult;
      } catch (postErr) {
        postFailed = true;
        recordDefinitionLifecycleToolingFailure(
          lifecycleAttemptBinding,
          postErr,
          "POST_HOOK_FAILED",
          writeErr,
          result,
        );
        if (mode === "envelope") {
          if (postErr instanceof FatalPostHookError) {
            envelope.addFatal(postErr.code, postErr.message);
          } else {
            envelope.addWarning("POST_HOOK_FAILED", postErr.message || String(postErr));
          }
        } else {
          writeErr(`[post hook] ${postErr.message || postErr}\n`);
        }
      }
    }
    // Nonblocking evidence is an audit record, not a lifecycle transition.
    // Record it after the ordinary hook has durably recorded the check
    // attempt.  Failed Envelopes still reach this hook, but a stale artifact
    // alone is never accepted as a newly completed attempt.
    if (entry.nonblockingPost && !hookCtx.flowOutboxResumed) {
      try {
        await entry.nonblockingPost(hookCtx, result);
      } catch (nonblockingError) {
        postFailed = true;
        recordDefinitionLifecycleToolingFailure(
          lifecycleAttemptBinding,
          nonblockingError,
          "NONBLOCKING_POST_FAILED",
          writeErr,
        );
        if (mode === "envelope") {
          envelope.addWarning("NONBLOCKING_EVIDENCE_RECORD_FAILED", nonblockingError.message || String(nonblockingError));
          envelope.ok = false;
          envelope.errors.push({
            level: "fatal",
            code: "NONBLOCKING_EVIDENCE_RECORD_FAILED",
            messages: [nonblockingError.message || String(nonblockingError)],
          });
          attachNonblockingContinuation(envelope, hookCtx, "The nonblocking evidence record was not durably saved.");
        } else {
          writeErr(`[nonblocking evidence] ${nonblockingError.message || nonblockingError}\n`);
        }
      }
    }
    if (deferFinalizeCompletion) {
      closeRuntimeLog();
      try {
        await persistFinalizeCleanupPostReturnMetadata({
          envelopeKey,
          hookCtx,
          metadata: closedRuntimeLogMetadata,
          commandModule: mod,
          commitCompletion: true,
        });
      } catch (completionError) {
        postFailed = true;
        recordDefinitionLifecycleToolingFailure(
          lifecycleAttemptBinding,
          completionError,
          "FINALIZE_COMPLETION_COMMIT_FAILED",
          writeErr,
        );
        if (mode === "envelope") {
          envelope.addFatal(
            "FINALIZE_COMPLETION_COMMIT_FAILED",
            completionError.message || String(completionError),
          );
        } else {
          writeErr(`[finalize completion] ${completionError.message || completionError}\n`);
        }
      }
    }
    if (mode === "envelope") {
      settleTypedStepOutcome(envelope, result);
      if (envelope.ok === false) {
        attachNonblockingContinuation(envelope, hookCtx, "The normal Flow operation did not complete.");
      }
      if (envelope instanceof Envelope && envelope.ok === false) attachRuntimeLog(envelope, runtimeLog?.metadata);
      writeOut(JSON.stringify(envelope.toJSON(), null, 2) + "\n");
      emitFinalizeCleanupReportDisplay({ envelopeKey, envelope, writeErr });
      setExit(envelope.ok && !postFailed ? 0 : 1);
    } else if (postFailed) {
      setExit(1);
    }
    closeRuntimeLog();
    if (!deferFinalizeCompletion) {
      await persistFinalizeCleanupPostReturnMetadata({
        envelopeKey,
        hookCtx,
        metadata: closedRuntimeLogMetadata,
        commandModule: mod,
      });
    }
    persistRuntimeLogMetadata(result);
    if (restoreStreams) restoreStreams();
    return;
  }

  // 8b. Failure path
  if (entry.onError) {
    try {
      await entry.onError(hookCtx, caught);
    } catch (onErrorErr) {
      writeErr(`[onError hook] ${onErrorErr.message || onErrorErr}\n`);
    }
  }
  recordDefinitionLifecycleToolingFailure(
    lifecycleAttemptBinding,
    caught,
    "COMMAND_FAILED",
    writeErr,
  );
  await emitFailure({
    err: caught,
    mode,
    envelopeType,
    envelopeKey,
    writeOut,
    writeErr,
    setExit,
    runtimeLogMetadata: runtimeLog?.metadata,
    flowContext: hookCtx,
  });
  closeRuntimeLog();
  await persistFinalizeCleanupPostReturnMetadata({
    envelopeKey,
    hookCtx,
    metadata: closedRuntimeLogMetadata,
    commandModule: mod,
  });
  persistRuntimeLogMetadata(null);
  if (restoreStreams) restoreStreams();
}

async function resolveOutputMode(entry) {
  try {
    const mod = await entry.command();
    return mod.default?.outputMode || "raw";
  } catch {
    return "raw";
  }
}

function emitFailure({
  err,
  mode,
  envelopeType,
  envelopeKey,
  writeOut,
  writeErr,
  setExit,
  runtimeLogMetadata,
  flowContext,
}) {
  if (mode === "envelope") {
    const code = err?.code || "ERROR";
    const env = Envelope.fail(envelopeType || "run", envelopeKey || "?", code, String(err?.message || err));
    const errorData = err?.data !== undefined
      ? err.data
      : err instanceof AgentFailure
        ? err.toJSON()
        : undefined;
    if (errorData !== undefined) env.data = errorData;
    if (err?.continuation) {
      try {
        attachFlowContinuation(env, FlowContinuation.fromStored(err.continuation));
      } catch {
        attachNonblockingContinuation(env, flowContext, "The normal Flow operation did not complete.");
      }
    } else {
      attachNonblockingContinuation(env, flowContext, "The normal Flow operation did not complete.");
    }
    attachRuntimeLog(env, runtimeLogMetadata);
    writeOut(JSON.stringify(env.toJSON(), null, 2) + "\n");
  } else {
    writeErr(`${err?.stack || err?.message || err}\n`);
    if (runtimeLogMetadata) {
      writeErr(`runtimeLog.runId=${runtimeLogMetadata.runId} runtimeLog.sequence=${runtimeLogMetadata.sequence}\n`);
    }
  }
  setExit(err?.exitCode ?? 1);
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { FlowSpecId } from "./flow-spec-id.js";
import { Envelope } from "./flow-envelope.js";

const MAX_TARGET_TOKEN_LENGTH = 300;
const MAX_FLOW_TARGET_BINDING_TOKEN_BYTES = 32 * 1024;
const FLOW_TARGET_BINDING_VERSION = 2;
const FLOW_TARGET_BINDING_MODES = new Set(["branch", "direct", "worktree"]);

function normalizedToken(value, field) {
  if (value == null) return null;
  if (typeof value !== "string" || value.trim() === "" || value.length > MAX_TARGET_TOKEN_LENGTH) {
    throw new Error(`${field} must be a non-empty string up to ${MAX_TARGET_TOKEN_LENGTH} characters`);
  }
  return value.trim();
}

function normalizedIssue(value) {
  if (value == null) return null;
  const issue = Number(value);
  if (!Number.isSafeInteger(issue) || issue < 1) {
    throw new Error(`--expect-issue must be a positive integer: ${value}`);
  }
  return issue;
}

function normalizedSpec(value) {
  const token = normalizedToken(value, "--expect-spec");
  if (token == null) return null;
  try {
    return FlowSpecId.from(token).toString();
  } catch {
    throw new Error("--expect-spec must be a literal specId");
  }
}

function normalizedRunId(value) {
  return normalizedToken(value, "--expect-run-id");
}

function activeIssueOf(state) {
  return state?.issue == null ? null : Number(state.issue);
}

function activeSpecOf(state) {
  return state?.specId ?? null;
}

function activeRunIdOf(state) {
  return state?.runId || null;
}

function requireFlowState(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw new Error("FlowTargetBinding requires active Flow state");
  }
  return input;
}

function canonicalDirectory(input, field) {
  if (typeof input !== "string" || !path.isAbsolute(input)) {
    throw new Error(`${field} must be an absolute directory`);
  }
  const resolved = path.resolve(input);
  let stat;
  let canonical;
  try {
    stat = fs.lstatSync(resolved);
    canonical = fs.realpathSync(resolved);
  } catch (cause) {
    throw new Error(`${field} is unavailable: ${resolved}`, { cause });
  }
  if (!stat.isDirectory() || stat.isSymbolicLink() || canonical !== resolved) {
    throw new Error(`${field} must be a canonical real directory: ${resolved}`);
  }
  return canonical;
}

function flowIssue(state) {
  const issue = state.issue ?? null;
  if (issue == null) return null;
  if (typeof issue !== "number" || !Number.isSafeInteger(issue) || issue < 1) {
    throw new Error("FlowTargetBinding issue must be a positive integer or null");
  }
  return issue;
}

function requireBranch(value, field) {
  if (typeof value !== "string" || value.trim() === "" || value.length > MAX_TARGET_TOKEN_LENGTH) {
    throw new Error(`FlowTargetBinding ${field} must be a non-empty branch name`);
  }
  return value.trim();
}

function flowAuthorityMode(flowState) {
  const mode = flowState?.execution?.mode;
  if (!FLOW_TARGET_BINDING_MODES.has(mode)) {
    throw new Error("FlowTargetBinding requires canonical execution.mode");
  }
  return mode;
}

class FlowExecutionAuthority {
  constructor(mode, mainRoot, executionRoot) {
    if (new.target === FlowExecutionAuthority) {
      throw new Error("FlowExecutionAuthority is abstract");
    }
    if (!FLOW_TARGET_BINDING_MODES.has(mode)) {
      throw new Error(`unsupported Flow target authority mode: ${mode}`);
    }
    this.mode = mode;
    this.mainRoot = canonicalDirectory(mainRoot, "FlowTargetBinding mainRoot");
    this.executionRoot = canonicalDirectory(executionRoot, "FlowTargetBinding executionRoot");
  }

  get dispatchLockRoot() {
    return this.mainRoot;
  }

  equals(other) {
    return other instanceof FlowExecutionAuthority
      && JSON.stringify(this.toJSON()) === JSON.stringify(other.toJSON());
  }

  static capture({ mode, flowState, mainRoot, authorityRoot, worktreePath }) {
    const activeMode = flowAuthorityMode(flowState);
    if (mode != null && mode !== activeMode) {
      throw new FlowTargetBindingMismatchError({
        expectedMode: mode ?? null,
        activeMode,
      });
    }
    if (activeMode === "worktree") {
      return new ManagedWorktreeFlowAuthority({
        mainRoot,
        executionRoot: authorityRoot,
        worktreePath: worktreePath ?? authorityRoot,
      });
    }
    if (activeMode === "branch" || activeMode === "direct") {
      return new BranchFlowAuthority({
        mode: activeMode,
        mainRoot,
        executionRoot: authorityRoot,
        featureBranch: flowState.featureBranch,
        baseBranch: flowState.baseBranch,
      });
    }
    throw new Error(`unsupported Flow target authority mode: ${activeMode}`);
  }

  static fromStored(value) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      throw new Error("stored Flow target authority must be an object");
    }
    if (value.mode === "worktree") return new ManagedWorktreeFlowAuthority(value);
    if (value.mode === "branch" || value.mode === "direct") return new BranchFlowAuthority(value);
    throw new Error(`unsupported stored Flow target authority mode: ${value.mode}`);
  }
}

class BranchFlowAuthority extends FlowExecutionAuthority {
  constructor({ mode = "branch", mainRoot, executionRoot, featureBranch = null, baseBranch = null }) {
    super(mode, mainRoot, executionRoot);
    if (this.executionRoot !== this.mainRoot) {
      throw new Error(`${mode} Flow execution root must equal the canonical main repository`);
    }
    if (mode === "branch" && ((featureBranch === null) !== (baseBranch === null))) {
      throw new Error("FlowTargetBinding branch authority requires both branch names or neither");
    }
    if (mode === "direct" && featureBranch !== null) {
      throw new Error("FlowTargetBinding direct authority must not have a feature branch");
    }
    this.featureBranch = featureBranch === null ? null : requireBranch(featureBranch, "featureBranch");
    this.baseBranch = baseBranch === null ? null : requireBranch(baseBranch, "baseBranch");
    Object.freeze(this);
  }

  toJSON() {
    return {
      mode: this.mode,
      mainRoot: this.mainRoot,
      executionRoot: this.executionRoot,
      featureBranch: this.featureBranch,
      baseBranch: this.baseBranch,
    };
  }
}

class ManagedWorktreeFlowAuthority extends FlowExecutionAuthority {
  constructor({ mainRoot, executionRoot, worktreePath }) {
    super("worktree", mainRoot, executionRoot);
    this.worktreePath = canonicalDirectory(
      worktreePath,
      "FlowTargetBinding managed worktree path",
    );
    if (this.executionRoot !== this.worktreePath) {
      throw new Error("managed worktree execution root must equal the owned worktree path");
    }
    if (this.worktreePath === this.mainRoot) {
      throw new Error("managed worktree authority must differ from the main repository");
    }
    Object.freeze(this);
  }

  toJSON() {
    return {
      mode: this.mode,
      mainRoot: this.mainRoot,
      executionRoot: this.executionRoot,
      worktreePath: this.worktreePath,
    };
  }
}

export class FlowTargetBindingMismatchError extends Error {
  constructor(data) {
    super("active Flow authority no longer matches the captured FlowTargetBinding");
    this.name = "FlowTargetBindingMismatchError";
    this.code = "ACTIVE_FLOW_MISMATCH";
    this.data = Object.freeze({ ...data });
  }
}

function bindingMismatch(expected, active) {
  const mismatches = {};
  for (const [field, expectedKey, activeKey] of [
    ["runId", "expectedRunId", "activeRunId"],
    ["issue", "expectedIssue", "activeIssue"],
    ["specId", "expectedSpec", "activeSpec"],
  ]) {
    if (expected[field] !== active[field]) {
      mismatches[expectedKey] = expected[field];
      mismatches[activeKey] = active[field];
    }
  }
  const expectedAuthority = expected.authority;
  const activeAuthority = active.authority;
  for (const [field, label] of [
    ["mode", "Mode"],
    ["mainRoot", "MainRoot"],
    ["executionRoot", "ExecutionRoot"],
    ["worktreePath", "WorktreePath"],
    ["featureBranch", "FeatureBranch"],
    ["baseBranch", "BaseBranch"],
  ]) {
    const expectedValue = expectedAuthority[field] ?? null;
    const activeValue = activeAuthority[field] ?? null;
    if (expectedValue !== activeValue) {
      mismatches[`expected${label}`] = expectedValue;
      mismatches[`active${label}`] = activeValue;
    }
  }
  return mismatches;
}

export class FlowTargetBinding {
  constructor({ version = FLOW_TARGET_BINDING_VERSION, runId, issue, specId, authority }) {
    if (version !== FLOW_TARGET_BINDING_VERSION) {
      throw new Error(`unsupported FlowTargetBinding version: ${version}`);
    }
    this.version = version;
    this.runId = normalizedRunId(runId);
    if (this.runId == null) throw new Error("FlowTargetBinding runId is required");
    this.issue = flowIssue({ issue });
    this.specId = normalizedSpec(specId);
    if (this.specId == null) throw new Error("FlowTargetBinding specId is required");
    this.authority = authority instanceof FlowExecutionAuthority
      ? authority
      : FlowExecutionAuthority.fromStored(authority);
    Object.freeze(this);
  }

  static capture(input = {}) {
    const flowState = requireFlowState(input.flowState);
    return new FlowTargetBinding({
      runId: flowState.runId,
      issue: flowIssue(flowState),
      specId: flowState.specId,
      authority: FlowExecutionAuthority.capture({
        ...input,
        flowState,
      }),
    });
  }

  static captureContext(ctx, flowState = ctx?.flowState) {
    if (!ctx || typeof ctx !== "object" || Array.isArray(ctx)) {
      throw new Error("FlowTargetBinding context is required");
    }
    return FlowTargetBinding.capture({
      flowState,
      mainRoot: ctx.mainRoot || ctx.root,
      authorityRoot: ctx.executionRoot || ctx.root,
      worktreePath: flowState?.execution?.mode === "worktree" ? (ctx.executionRoot || ctx.root) : undefined,
    });
  }

  static deserialize(token) {
    if (typeof token !== "string" || token.trim() === "") {
      throw new Error("serialized FlowTargetBinding is required");
    }
    if (Buffer.byteLength(token) > MAX_FLOW_TARGET_BINDING_TOKEN_BYTES) {
      throw new Error(`serialized FlowTargetBinding must not exceed ${MAX_FLOW_TARGET_BINDING_TOKEN_BYTES} bytes`);
    }
    let value;
    try {
      value = JSON.parse(Buffer.from(token, "base64url").toString("utf8"));
    } catch (cause) {
      throw new Error("serialized FlowTargetBinding is invalid", { cause });
    }
    return new FlowTargetBinding(value);
  }

  get digest() {
    return crypto.createHash("sha256").update(JSON.stringify(this.toJSON())).digest("hex");
  }

  get dispatchLockRoot() {
    return this.authority.dispatchLockRoot;
  }

  serialize() {
    return Buffer.from(JSON.stringify(this.toJSON()), "utf8").toString("base64url");
  }

  guardCommand(command) {
    if (typeof command !== "string" || command.trim() === "") {
      throw new Error("FlowTargetBinding guarded command is required");
    }
    const issueGuard = this.issue == null
      ? " --expect-no-issue"
      : "";
    return `${command.trim()} --expect-binding '${this.serialize()}'${issueGuard}`;
  }

  mismatchAgainst(input) {
    let active;
    try {
      active = FlowTargetBinding.capture(input);
    } catch (error) {
      if (error?.code === "ACTIVE_FLOW_MISMATCH") throw error;
      throw new FlowTargetBindingMismatchError({
        expectedAuthority: this.authority.toJSON(),
        activeAuthorityInvalid: error?.message || String(error),
      });
    }
    const mismatches = bindingMismatch(this.toJSON(), active.toJSON());
    return Object.keys(mismatches).length === 0 ? null : mismatches;
  }

  assertCurrent(input) {
    const mismatch = this.mismatchAgainst(input);
    if (mismatch) throw new FlowTargetBindingMismatchError(mismatch);
    return this;
  }

  runIfCurrent(input, mutation) {
    if (typeof mutation !== "function") {
      throw new Error("FlowTargetBinding mutation callback is required");
    }
    this.assertCurrent(input);
    return mutation();
  }

  toJSON() {
    return {
      version: this.version,
      runId: this.runId,
      issue: this.issue,
      specId: this.specId,
      authority: this.authority.toJSON(),
    };
  }
}

export class FlowTargetExpectation {
  constructor(input = {}) {
    this.binding = input.expectBinding == null
      ? null
      : FlowTargetBinding.deserialize(input.expectBinding);
    this.issue = normalizedIssue(input.expectIssue);
    this.issueAbsent = input.expectNoIssue === true;
    if (this.issue != null && this.issueAbsent) {
      throw new Error("--expect-issue and --expect-no-issue cannot be used together");
    }
    this.specId = normalizedSpec(input.expectSpec);
    this.runId = normalizedRunId(input.expectRunId ?? input.expectRunID);
    if (this.binding) {
      const mismatch = this.mismatchAgainst(this.binding.toJSON());
      if (mismatch) {
        throw new Error("explicit target guards conflict with --expect-binding");
      }
    }
    Object.freeze(this);
  }

  get effectiveRunId() {
    return this.runId ?? this.binding?.runId ?? null;
  }

  get effectiveSpecId() {
    return this.specId ?? this.binding?.specId ?? null;
  }

  get effectiveIssue() {
    return this.issue ?? this.binding?.issue ?? null;
  }

  get expectsNoIssue() {
    return this.issueAbsent || (this.binding != null && this.binding.issue == null);
  }

  get empty() {
    return this.binding == null
      && this.issue == null
      && !this.issueAbsent
      && this.specId == null
      && this.runId == null;
  }

  mismatchAgainst(state) {
    if (this.empty || !state) return null;
    const mismatches = {};
    const expectedIssue = this.effectiveIssue;
    const expectsNoIssue = this.expectsNoIssue;
    const expectedSpec = this.effectiveSpecId;
    const expectedRunId = this.effectiveRunId;
    const activeIssue = activeIssueOf(state);
    const activeSpec = activeSpecOf(state);
    const activeRunId = activeRunIdOf(state);
    if (expectedIssue != null && activeIssue !== expectedIssue) {
      mismatches.expectedIssue = expectedIssue;
      mismatches.activeIssue = activeIssue;
    }
    if (expectsNoIssue && activeIssue !== null) {
      mismatches.expectedIssue = null;
      mismatches.activeIssue = activeIssue;
    }
    if (expectedSpec != null && activeSpec !== expectedSpec) {
      mismatches.expectedSpec = expectedSpec;
      mismatches.activeSpec = activeSpec;
    }
    if (expectedRunId != null && activeRunId !== expectedRunId) {
      mismatches.expectedRunId = expectedRunId;
      mismatches.activeRunId = activeRunId;
    }
    if (Object.keys(mismatches).length === 0) return null;
    return {
      ...mismatches,
      ...((expectedIssue != null || expectsNoIssue) && !("expectedIssue" in mismatches) && {
        expectedIssue,
        activeIssue,
      }),
      ...(expectedSpec != null && !("expectedSpec" in mismatches) && { expectedSpec, activeSpec }),
      ...(expectedRunId != null && !("expectedRunId" in mismatches) && { expectedRunId, activeRunId }),
    };
  }
}

function mismatchSummary(data) {
  if ("expectedIssue" in data && data.expectedIssue !== data.activeIssue) {
    if (data.expectedIssue == null) {
      return `Another flow is active for Issue #${data.activeIssue} but the specified target expects no Issue.`;
    }
    return `Another flow is active for Issue #${data.activeIssue ?? "none"} and does not match the specified #${data.expectedIssue}.`;
  }
  if ("expectedSpec" in data && data.expectedSpec !== data.activeSpec) {
    return `Another flow is active for spec ${data.activeSpec ?? "none"} and does not match the specified spec ${data.expectedSpec}.`;
  }
  if ("expectedRunId" in data && data.expectedRunId !== data.activeRunId) {
    return `Another flow is active for runId ${data.activeRunId ?? "none"} and does not match the specified runId ${data.expectedRunId}.`;
  }
  return "Another flow is active and does not match the specified target.";
}

export function buildTargetMismatchEnvelope({ type, key, data }) {
  const envelope = Envelope.fail(
    type,
    key,
    "ACTIVE_FLOW_MISMATCH",
    [
      mismatchSummary(data),
      "Stop before dispatching next-action, repair, run, finalize, or cleanup.",
    ],
    data,
  );
  envelope.errors[0].data = envelope.data;
  return envelope;
}

export function targetMismatchEnvelopeForInput({
  type,
  key,
  input,
  expectation: suppliedExpectation = null,
  flowState,
  mainRoot = null,
  authorityRoot = null,
  worktreePath = null,
  context = null,
}) {
  let expectation;
  try {
    expectation = suppliedExpectation ?? new FlowTargetExpectation(input);
    if (!(expectation instanceof FlowTargetExpectation)) {
      throw new Error("target expectation must be a FlowTargetExpectation");
    }
  } catch (err) {
    return Envelope.fail(type, key, "ARGS_ERROR", err.message);
  }
  if (expectation.binding) {
    if (context) {
      try {
        const active = FlowTargetBinding.captureContext(context, flowState);
        const data = bindingMismatch(expectation.binding.toJSON(), active.toJSON());
        if (Object.keys(data).length > 0) {
          return buildTargetMismatchEnvelope({ type, key, data });
        }
      } catch (err) {
        if (err?.code === "ACTIVE_FLOW_MISMATCH") {
          return buildTargetMismatchEnvelope({ type, key, data: err.data });
        }
        return buildTargetMismatchEnvelope({
          type,
          key,
          data: {
            expectedAuthority: expectation.binding.authority.toJSON(),
            activeAuthorityInvalid: err?.message || String(err),
          },
        });
      }
    } else {
    if (!flowState || !mainRoot || !authorityRoot) {
      return buildTargetMismatchEnvelope({
        type,
        key,
        data: {
          expectedRunId: expectation.binding.runId,
          activeRunId: activeRunIdOf(flowState),
        },
      });
    }
    try {
      expectation.binding.assertCurrent({
        flowState,
        mainRoot,
        authorityRoot,
        worktreePath: worktreePath ?? (flowState?.worktree === true ? authorityRoot : undefined),
      });
    } catch (err) {
      if (err?.code !== "ACTIVE_FLOW_MISMATCH") throw err;
      return buildTargetMismatchEnvelope({ type, key, data: err.data });
    }
    }
  }
  const data = expectation.mismatchAgainst(flowState);
  if (!data) return null;
  return buildTargetMismatchEnvelope({ type, key, data });
}

export function missingExactTargetGuardNames(input = {}, state = {}) {
  if (input.expectBinding != null) return [];
  const missing = [];
  if (input.expectRunId == null) missing.push("--expect-run-id");
  if (input.expectSpec == null) missing.push("--expect-spec");
  if (state.issue == null) {
    if (input.expectNoIssue !== true) missing.push("--expect-no-issue");
  } else if (input.expectIssue == null) {
    missing.push("--expect-issue");
  }
  return missing;
}

#!/usr/bin/env node
/**
 * src/sennel.js
 *
 * sennel CLI entry point.
 * Routes top-level subcommands to dedicated dispatchers:
 *   docs    → src/docs.js
 *   flow    → src/flow.js
 *   check   → src/check.js
 *   metrics → src/metrics.js
 *   spec    → src/spec.js
 *   hook    → src/hook.js
 *   setup   → src/setup.js
 *   upgrade → src/upgrade.js
 *   migrate → src/migrate.js
 *   help    → src/help.js
 */

import { EXIT_ERROR } from "./lib/constants.js";
import { initContainer } from "./lib/container.js";
import { FinalizeCleanupRoute } from "./lib/finalize-cleanup-paths.js";
import { executeWorktreeLocalCli } from "./lib/worktree-cli-execution.js";

const rawArgs = process.argv.slice(2);
const isFlowQuery = rawArgs[0] === "flow" && rawArgs[1] === "query";
if (isFlowQuery) {
  // Query input is the only bootstrap boundary allowed before worktree
  // resolution. Query is read-only and executes against the caller-selected
  // root without resolving or re-executing another worktree's CLI source.
  const { bootstrapFlowQueryCli } = await import("./flow/query.js");
  process.exit(await bootstrapFlowQueryCli(rawArgs.slice(2)));
}
const worktreeCliExitCode = executeWorktreeLocalCli({ argv: rawArgs });
if (worktreeCliExitCode != null) process.exit(worktreeCliExitCode);
const [subCmd, ...rest] = rawArgs;
const recoveryWithoutFlowAttribution = subCmd === "flow"
  && rest[0] === "run"
  && rest[1] === "abort";
let agentWorkDirOverride = null;
const enableFinalizeCleanupDurablePaths = FinalizeCleanupRoute
  .fromCliArgs(rawArgs)
  .removesManagedWorktree;
if (subCmd === "flow" && rest[0] === "run") {
  for (let i = 2; i < rest.length; i += 1) {
    if (rest[i] === "--agent-work-dir") {
      const value = rest[i + 1];
      const normalized = value == null ? "" : String(value).trim();
      if (normalized !== "" && !normalized.startsWith("-")) agentWorkDirOverride = normalized;
      break;
    }
  }
}

// version (-v / --version / -V)
if (subCmd === "-v" || subCmd === "--version" || subCmd === "-V") {
  const { getPackageVersion } = await import("./lib/cli.js");
  console.log(getPackageVersion());
  process.exit(0);
}

// help (no args / -h / --help / help [topic])
if (!subCmd || subCmd === "-h" || subCmd === "--help" || subCmd === "help") {
  initContainer({ entryCommand: rawArgs.join(" "), allowInvalidConfig: true });
  const { coreCommandRegistry } = await import("./lib/command-registry.js");
  await coreCommandRegistry.find(["help"]).entrypoint.execute(subCmd === "help" ? rest : []);
  process.exit(0);
}

function isHelpRequest(args) {
  return args.includes("-h") || args.includes("--help");
}

function helpTopic(head, args) {
  return [head, ...args.filter((arg) => arg !== "-h" && arg !== "--help")];
}

async function renderSharedHelp(argv) {
  initContainer({ entryCommand: rawArgs.join(" "), allowInvalidConfig: true });
  const { renderHelp } = await import("./help.js");
  console.log(await renderHelp({ root: process.cwd(), argv }));
  process.exit(0);
}

const { coreCommandRegistry } = await import("./lib/command-registry.js");
const definition = coreCommandRegistry.find([subCmd]);
const sharedHelpTopic = helpTopic(subCmd, rest);
if (definition && isHelpRequest(rest) && coreCommandRegistry.find(sharedHelpTopic)) {
  await renderSharedHelp([subCmd, ...rest]);
}

// Initialize the shared dependency container once; dispatchers and commands
// below import `container` directly from ./lib/container.js.
initContainer({
  entryCommand: rawArgs.join(" "),
  agentWorkDirOverride,
  flowAttribution: subCmd === "docs" || recoveryWithoutFlowAttribution ? "none" : "ambient",
  finalizeCleanupDurablePaths: enableFinalizeCleanupDurablePaths,
  allowInvalidConfig: definition?.allowInvalidConfig === true || !definition,
});

if (definition) {
  try {
    await definition.entrypoint.execute(rest);
  } catch (err) {
    console.error(err?.stack || String(err));
    process.exit(EXIT_ERROR);
  }
} else {
  try {
    const { repoRoot } = await import("./lib/cli.js");
    const { dispatchPluginCommand, loadPluginRegistry } = await import("./lib/plugin-registry.js");
    const root = repoRoot();
    if (isHelpRequest(rest) && loadPluginRegistry(root).resolveCommand(subCmd)) {
      await renderSharedHelp([subCmd, ...rest]);
    }
    const handled = await dispatchPluginCommand(root, subCmd, rest);
    if (handled) {
      if (handled.ok != null) {
        if (handled.ok && handled.key === "help" && typeof handled.data?.help === "string") {
          console.log(handled.data.help);
          process.exit(0);
        }
        console.log(JSON.stringify(handled, null, 2));
        process.exit(handled.ok ? 0 : (handled.exitCode || EXIT_ERROR));
      }
      process.exit(0);
    }
    if (isHelpRequest(rest)) {
      await renderSharedHelp([subCmd, ...rest]);
    }
    console.error(`sennel: unknown command '${subCmd}' is unavailable. Enable a plugin that contributes this command, or run: sennel plugin list`);
  } catch (err) {
    console.error(`sennel: unknown command '${subCmd}' is unavailable. Plugin command resolution failed: ${err.message}`);
  }
  console.error("Run: sennel help");
  process.exit(EXIT_ERROR);
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { join } from "path";
import { execFileSync } from "child_process";
import { buildCoreHelpModel, commands } from "../../src/help.js";
import { allCommands } from "../../src/lib/command-registry.js";

const CMD = join(process.cwd(), "src/sennel.js");
const CMD_ARGS_PREFIX = ["help"];

describe("help", () => {
  it("exports command metadata registry", () => {
    assert.equal(Array.isArray(commands), false);
    assert.equal(typeof commands.findCommand, "function");
  });

  it("has expected commands in namespace groups", () => {
    const names = buildCoreHelpModel({ commands: allCommands, lang: "en" }).allCommands().map((c) => c.name);
    assert.ok(names.includes("help"));
    assert.ok(names.includes("setup"));
    assert.ok(names.includes("docs build"));
    assert.ok(names.includes("flow get"));
    assert.ok(names.includes("flow set"));
    assert.ok(names.includes("flow run"));
  });

  it("does not include old flat commands", () => {
    const names = buildCoreHelpModel({ commands: allCommands, lang: "en" }).topLevelCommands().map((c) => c.fullName || c.name);
    assert.ok(!names.includes("build"), "should not have flat 'build'");
    assert.ok(!names.includes("gate"), "should not have flat 'gate'");
    assert.ok(!names.includes("scan"), "should not have flat 'scan'");
  });

  it("has namespace sections", () => {
    const sections = buildCoreHelpModel({ commands: allCommands, lang: "en" }).topLevelCommands().map((c) => c.section);
    assert.ok(sections.includes("Docs"));
    assert.ok(sections.includes("Flow"));
  });

  it("prints help output via CLI", () => {
    const result = execFileSync("node", [CMD, ...CMD_ARGS_PREFIX], { encoding: "utf8" });
    assert.match(result, /sennel/);
    assert.match(result, /Commands|コマンド一覧/);
  });

  it("prints plugin subcommands via CLI", () => {
    const result = execFileSync("node", [CMD, "plugin", "--help"], { encoding: "utf8" });
    assert.match(result, /Subcommands:/);
    assert.match(result, /source\s+Manage plugin sources/);
    assert.match(result, /find\s+Find installable plugin packages/);
    assert.match(result, /update\s+Update installed plugin packages/);
    assert.doesNotMatch(result, /update-all/);
  });

  it("prints plugin command options via CLI", () => {
    const result = execFileSync("node", [CMD, "plugin", "find", "--help"], { encoding: "utf8" });
    assert.match(result, /Usage: sennel plugin find \[--json\]/);
    assert.match(result, /--json/);
  });
});

import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { afterEach, describe, it } from "node:test";

import {
  CommandDefinition,
  CommandRegistry,
  coreCommandRegistry,
} from "../../../src/lib/command-registry.js";
import { PluginCatalog, PluginManifest } from "../../../src/lib/plugin-registry.js";
import { FLOW_COMMANDS } from "../../../src/flow/registry.js";
import { createTmpDir, removeTmpDir } from "../../support/builders/tmp-dir.js";

describe("CommandDefinition registry", () => {
  it("derives exactly the same help and executable route sets", () => {
    assert.deepEqual(coreCommandRegistry.helpPaths(), coreCommandRegistry.routePaths());
    assert.ok(coreCommandRegistry.routePaths().includes("docs build"));
    assert.ok(coreCommandRegistry.routePaths().includes("check config"));
    assert.ok(coreCommandRegistry.routePaths().includes("spec render"));
    assert.ok(coreCommandRegistry.routePaths().includes("metrics review"));
    assert.ok(!coreCommandRegistry.routePaths().includes("docs snapshot"));
  });

  it("rejects duplicate command registration", () => {
    const registry = new CommandRegistry([
      new CommandDefinition({
        name: "sample",
        help: { summary: "first" },
        entrypoint: { modulePath: "../help.js", invocation: "main" },
      }),
    ]);

    assert.throws(
      () => registry.register(new CommandDefinition({
        name: "sample",
        help: { summary: "duplicate" },
        entrypoint: { modulePath: "../help.js", invocation: "main" },
      })),
      /duplicate command: sample/,
    );
  });

  it("retains flow command dispatch and help metadata in one definition", () => {
    const definition = coreCommandRegistry.find(["flow", "run", "gate"]);
    const flowEntry = FLOW_COMMANDS.run.gate;
    assert.ok(definition instanceof CommandDefinition);
    assert.equal(definition.command, flowEntry.command);
    assert.equal(definition.outputMode, "envelope");
    assert.deepEqual(definition.args, flowEntry.args);
    assert.equal(definition.requiresFlow, flowEntry.requiresFlow);
    assert.equal(definition.runtimeLog, flowEntry.runtimeLog);
    assert.match(definition.help, /Usage: sennel flow run gate/);
    assert.equal(definition.metadata(["flow", "run"]).name, "flow run gate");
  });

  it("describes Version-1 gate and draft-reopen authorities without retired paths", () => {
    const gateHelp = FLOW_COMMANDS.run.gate.help;
    const reopenHelp = FLOW_COMMANDS.run["reopen-draft"].help;
    const autoCheckHelp = FLOW_COMMANDS.run["auto-check"].help;
    const recoverReviewHelp = FLOW_COMMANDS.run["recover-review-pass"].help;
    const requestHelp = FLOW_COMMANDS.set.request.help;
    const issueHelp = FLOW_COMMANDS.set.issue.help;
    const issueLogHelp = FLOW_COMMANDS.set["issue-log"].help;
    const noteHelp = FLOW_COMMANDS.set.note.help;
    const autoHelp = FLOW_COMMANDS.set.auto.help;
    const approvalHelp = FLOW_COMMANDS.set.approval.help;
    const overviewHelp = FLOW_COMMANDS.run["update-overview"].help;
    const testExecuteHelp = FLOW_COMMANDS.run["test-execute"].help;
    const testResultReviewHelp = FLOW_COMMANDS.run["test-result-review"].help;
    const retroHelp = FLOW_COMMANDS.run.retro.help;
    const finalRegressionHelp = FLOW_COMMANDS.run["final-regression"].help;
    const acceptanceReviewHelp = FLOW_COMMANDS.run["acceptance-review"].help;

    assert.match(gateHelp, /active Version-1 Flow/);
    assert.match(gateHelp, /directory \/ spec\.json/);
    assert.doesNotMatch(gateHelp, /legacy spec\.md|auto-resolved from flow\.json/i);
    assert.match(reopenHelp, /typed Version-1 Activity/);
    assert.match(reopenHelp, /cataloged issue-log\.json/);
    assert.doesNotMatch(reopenHelp, /<spec>\/issue-log\.json|flow\.json planRewinds/);
    assert.match(autoCheckHelp, /without adding a\s+mutable autoCheck field to flow\.json/);
    assert.doesNotMatch(autoCheckHelp, /persisted to the active flow\.json autoCheck/);
    assert.match(recoverReviewHelp, /retired projection recovery is never\s+eligible/);
    assert.doesNotMatch(recoverReviewHelp, /immutable review-history artifact|before mutation/);
    assert.match(requestHelp, /active Version-1 request is immutable/);
    assert.doesNotMatch(requestHelp, /Works in both active and preparing mode/);
    assert.match(issueHelp, /Issue identity and issue\.md are immutable/);
    assert.doesNotMatch(issueHelp, /Set the GitHub issue number in flow\.json/);
    assert.match(noteHelp, /typed note Activity/);
    assert.doesNotMatch(noteHelp, /note entry to state\.notes/);
    assert.match(autoHelp, /typed policy Activity/);
    assert.doesNotMatch(autoHelp, /Writes to flow\.json/);
    assert.match(issueLogHelp, /Activity-backed entry.*cataloged issue\.log/);
    assert.doesNotMatch(issueLogHelp, /entry in issue-log\.json/);
    assert.match(approvalHelp, /cataloged spec\.json/);
    assert.match(approvalHelp, /transient Markdown output/);
    assert.doesNotMatch(approvalHelp, /produce spec\.md/);
    assert.match(overviewHelp, /typed spec\.record/);
    assert.doesNotMatch(overviewHelp, /spec\.md is\s+re-rendered/);
    assert.equal(FLOW_COMMANDS.run["impl-confirm"], undefined);
    assert.equal(FLOW_COMMANDS.set.summary, undefined);
    assert.match(testExecuteHelp, /steps\/test-execute\/result\.json/);
    assert.equal(FLOW_COMMANDS.run["scenario-validity"], undefined);
    assert.match(testResultReviewHelp, /steps\/test-result-review\/result\.json/);
    assert.match(retroHelp, /steps\/impl\/retro\/result\.json/);
    assert.equal(FLOW_COMMANDS.run.retro.args.flags.includes("--force"), false);
    assert.match(finalRegressionHelp, /steps\/final-regression\/result\.json/);
    assert.match(acceptanceReviewHelp, /steps\/acceptance-review\/result\.json/);
    for (const help of [testExecuteHelp, testResultReviewHelp, retroHelp, finalRegressionHelp, acceptanceReviewHelp]) {
      assert.doesNotMatch(help, /<configured-spec-root>|tests\/\.raw\/|test-execute-result\.json|test-result-review\.json|retro\.json|final-regression-result\.json|acceptance-review\.json/);
    }
  });

  it("renders the complete canonical help for flow leaf commands", () => {
    const definition = coreCommandRegistry.find(["flow", "resume"]);
    assert.equal(definition.help, FLOW_COMMANDS.resume.help);
    assert.equal(definition.metadata(["flow"]).help, FLOW_COMMANDS.resume.help);
    assert.match(definition.help, /registered active flow/i);
  });
});

describe("plugin command registration", () => {
  let root;
  afterEach(() => root && removeTmpDir(root));

  function manifest(providerId) {
    const pluginRoot = path.join(root, providerId);
    fs.mkdirSync(pluginRoot, { recursive: true });
    return new PluginManifest(pluginRoot, {
      name: providerId,
      files: ["commands/"],
      contributions: {
        commands: [{ name: "collision", path: "commands/index.js" }],
      },
    }, providerId);
  }

  it("rejects duplicate plugin command contributions", () => {
    root = createTmpDir("plugin-command-duplicate-");
    assert.throws(
      () => new PluginCatalog(root, [manifest("first-plugin"), manifest("second-plugin")]),
      /duplicate plugin command: collision/,
    );
  });

  it("rejects a plugin override of a core command", () => {
    root = createTmpDir("plugin-core-override-");
    assert.throws(
      () => new PluginManifest(root, {
        name: "override-plugin",
        files: ["commands/"],
        contributions: {
          commands: [{ name: "docs", path: "commands/index.js" }],
        },
      }),
      /core command/,
    );
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";

describe("unified command registry (R3)", () => {
  it("exposes flow/docs/check/metrics subtrees individually without loading other domains eagerly", async () => {
    const mod = await import("../../../src/lib/command-registry.js");
    assert.ok(mod.flowCommands, "flowCommands subtree must be exported");
    assert.ok(mod.docsCommands, "docsCommands subtree must be exported");
    assert.ok(mod.checkCommands, "checkCommands subtree must be exported");
    assert.ok(mod.metricsCommands, "metricsCommands subtree must be exported");
  });

  it("provides combined tree allCommands = { flow, docs, check, metrics }", async () => {
    const mod = await import("../../../src/lib/command-registry.js");
    assert.ok(mod.allCommands, "allCommands root tree must be exported");
    assert.ok(mod.allCommands.flow);
    assert.ok(mod.allCommands.docs);
    assert.ok(mod.allCommands.check);
    assert.ok(mod.allCommands.metrics);
  });

  it("every entry declares command (lazy import) and outputMode", async () => {
    const { allCommands } = await import("../../../src/lib/command-registry.js");
    const visit = (node, pathParts = []) => {
      if (typeof node !== "object" || node == null) return;
      // An entry is identified by having `command` (lazy import) fn.
      if (typeof node.command === "function") {
        assert.ok(
          node.outputMode === "envelope" || node.outputMode === "raw",
          `entry ${pathParts.join(".")} must declare outputMode`,
        );
        return;
      }
      for (const [k, v] of Object.entries(node)) visit(v, [...pathParts, k]);
    };
    visit(allCommands);
  });

  it("no key collision across subtrees (unique paths)", async () => {
    const { allCommands } = await import("../../../src/lib/command-registry.js");
    const seen = new Set();
    const visit = (node, pathParts = []) => {
      if (typeof node !== "object" || node == null) return;
      if (typeof node.command === "function") {
        const key = pathParts.join(".");
        assert.equal(seen.has(key), false, `duplicate entry key: ${key}`);
        seen.add(key);
        return;
      }
      for (const [k, v] of Object.entries(node)) visit(v, [...pathParts, k]);
    };
    visit(allCommands);
    assert.ok(seen.size > 0);
  });

  it("flow run entries accept agent work dir but not removed log-file option", async () => {
    const { flowCommands } = await import("../../../src/lib/command-registry.js");
    const removedLogOption = `--log-${"file"}`;
    for (const [name, entry] of Object.entries(flowCommands.run)) {
      if (typeof entry?.command !== "function") continue;
      const options = entry.args?.options || [];
      assert.ok(options.includes("--agent-work-dir"), `flow run ${name} must accept --agent-work-dir`);
      assert.ok(!options.includes(removedLogOption), `flow run ${name} must not accept removed log option`);
    }
  });
});
